INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la sanction maximale que peut prononcer la commission des sanctions de l''AMF à l''encontre d''une personne morale ?', '["10 millions d''euros","100 millions d''euros","1 milliard d''euros"]', 1, 'La commission des sanctions peut infliger une amende maximale de 100 millions d''euros aux personnes morales.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quel est le délai de transmission à l''AMF du rapport annuel d''une société de gestion de portefeuille ?', '["4 mois","8 mois","6 mois"]', 2, 'Les sociétés de gestion doivent transmettre leur rapport annuel à l''AMF dans les six mois suivant la clôture de l''exercice.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quel est l''effet d''une hausse des taux d''intérêt sur le prix des obligations à taux fixe ?', '["Diminution","Augmentation","Aucun effet"]', 0, 'Une hausse des taux rend les obligations existantes moins attractives, entraînant une baisse de leur prix.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Que se passe-t-il si le cours d''un titre dépasse le prix limite d''un ordre d''achat à cours limité ?', '["L''ordre est exécuté","L''ordre reste en attente","L''ordre est rejeté"]', 1, 'Un ordre à cours limité d''achat n''est exécuté que si le cours est inférieur ou égal au prix limite ; sinon il reste en attente.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle autorité est compétente pour agréer les sociétés de gestion de portefeuille en France ?', '["AMF","ACPR","ESMA"]', 0, 'L''AMF est l''autorité chargée de délivrer les agréments aux sociétés de gestion de portefeuille.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la directive MiFID, quelle est la durée minimale de conservation des enregistrements des ordres par les prestataires de services d''investissement ?', '["3 ans","5 ans","10 ans"]', 1, 'La directive MiFID impose une conservation minimale de 5 ans pour les enregistrements des ordres.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur souhaite acheter 100 actions à un cours maximum de 50 euros. Quel type d''ordre doit-il passer pour garantir ce prix maximal ?', '["Ordre au marché","Ordre à seuil de déclenchement","Ordre à cours limité"]', 2, 'L''ordre à cours limité garantit un prix maximal, contrairement aux autres types d''ordres.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle autorité est responsable de l''agrément et de la surveillance des sociétés de gestion de portefeuille en France ?', '["L''ACPR","L''AMF","L''ESMA"]', 1, 'L''AMF est l''autorité compétente pour agréer et surveiller les sociétés de gestion en France.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle autorité européenne est chargée de la surveillance directe des agences de notation de crédit ?', '["ESMA","EBA","EIOPA"]', 0, 'L''ESMA a la compétence exclusive de surveillance des agences de notation dans l''UE.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel type d''ordre est exécuté immédiatement au meilleur prix disponible sur le marché ?', '["Ordre à cours limité","Ordre à seuil de déclenchement","Ordre au marché"]', 2, 'Un ordre au marché est exécuté immédiatement au meilleur prix disponible.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''un conseiller en investissements financiers (CIF) concernant son enregistrement ?', '["Il doit être enregistré auprès de l''ORIAS","Il doit être agréé par l''AMF","Il doit être immatriculé au registre du commerce"]', 0, 'Les CIF sont tenus de s''enregistrer auprès de l''ORIAS, pas d''obtenir un agrément AMF.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée minimale de conservation des enregistrements téléphoniques et communications électroniques par les entreprises d''investissement selon MIFID II ?', '["3 ans","5 ans","10 ans"]', 1, 'MIFID II impose une conservation d''au moins 5 ans pour ces enregistrements.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la différence entre un manquement d''initié et un délit d''initié ?', '["Le manquement est une violation administrative, le délit une infraction pénale","Le manquement concerne les personnes physiques, le délit les personnes morales","Le manquement est puni d''une amende, le délit d''une peine de prison uniquement"]', 0, 'Le manquement d''initié relève de la sanction administrative de l''AMF, le délit d''initié de la sanction pénale.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de conformité, que signifie le principe de proportionnalité dans la mise en œuvre des obligations réglementaires ?', '["Les obligations s''appliquent de manière identique à tous les acteurs","Les obligations sont adaptées à la taille, à la nature et à la complexité de l''activité","Les obligations sont réduites pour les acteurs les plus rentables"]', 1, 'Le principe de proportionnalité permet d''ajuster les exigences selon les caractéristiques de l''entité.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de prévention des conflits d''intérêts, quelle est l''obligation d''une société de gestion ?', '["Refuser toute opération susceptible de créer un conflit d''intérêts.","Mettre en place une politique de prévention et, si elle ne suffit pas, informer le client avant de traiter.","Déclarer à l''AMF chaque conflit d''intérêts rencontré."]', 1, 'La réglementation impose de prévenir les conflits, et à défaut, d''informer le client avant toute transaction.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la règle concernant les opérations personnelles des collaborateurs d''une société de gestion ?', '["Les collaborateurs ayant accès à des informations privilégiées doivent obtenir une autorisation préalable.","Tous les collaborateurs doivent déclarer leurs opérations à l''AMF.","Les opérations personnelles sont interdites pour tous les collaborateurs."]', 0, 'Seuls les collaborateurs ayant accès à des informations privilégiées sont soumis à une autorisation préalable.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'En matière de conformité, que signifie le principe de proportionnalité ?', '["Les obligations sont identiques pour tous les acteurs.","Les petites structures sont exonérées de toute obligation de conformité.","Les obligations sont adaptées à la nature, à la taille et à la complexité de l''activité."]', 2, 'Le principe de proportionnalité permet d''adapter les exigences réglementaires aux caractéristiques de l''acteur.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle obligation incombe à une société de gestion en matière de conformité ?', '["Mettre en place une fonction de conformité permanente, efficace et indépendante.","Désigner un responsable de la conformité qui doit être membre du directoire.","Externaliser obligatoirement la fonction de conformité à un prestataire agréé."]', 0, 'La réglementation impose une fonction de conformité permanente, efficace et indépendante au sein de la société de gestion.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle de l''AMF en matière de déontologie et de conformité ?', '["Édicter les règles de déontologie pour les entreprises cotées.","Contrôler le respect des obligations professionnelles des acteurs de marché.","Sanctionner les manquements à la déontologie des journalistes financiers."]', 1, 'L''AMF contrôle le respect des obligations professionnelles des acteurs de marché et peut sanctionner les manquements.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la lutte contre le blanchiment, que signifie l''approche par les risques ?', '["Appliquer les mêmes mesures de vigilance à tous les clients sans distinction.","Se concentrer uniquement sur les transactions supérieures à un seuil fixé.","Adapter les mesures de vigilance en fonction du niveau de risque présenté par le client."]', 2, 'L''approche par les risques consiste à moduler les mesures de vigilance selon le niveau de risque du client.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de lutte contre le blanchiment, à quelle autorité une société de gestion doit-elle déclarer les opérations suspectes ?', '["À l''AMF","À Tracfin","À l''ACPR"]', 1, 'Les sociétés de gestion déclarent les opérations suspectes à Tracfin, cellule de renseignement financier.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée légale de conservation des documents relatifs à la LCB-FT pour les professionnels assujettis ?', '["5 ans","10 ans","3 ans"]', 0, 'Les documents doivent être conservés 5 ans après la fin de la relation d''affaires ou l''opération.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre d''un embargo, que signifie le gel des avoirs ?', '["Interdiction de tout échange commercial avec le pays visé","Saisie définitive des biens des personnes désignées","Blocage des fonds et ressources économiques des personnes désignées"]', 2, 'Le gel des avoirs bloque les fonds sans transfert de propriété, contrairement à une saisie.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la conduite à tenir pour un virement vers un pays soumis à un embargo ?', '["Exécuter si le montant est inférieur à 10 000 euros","Refuser et signaler l''opération","Exécuter après vérification de l''identité du bénéficiaire"]', 1, 'Toute opération vers un pays sous embargo doit être refusée et signalée aux autorités compétentes.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation LCB-FT, quelle est l''obligation d''une entreprise d''assurance pour une opération occasionnelle ?', '["Déclarer systématiquement toute opération à Tracfin","Identifier le client et le bénéficiaire effectif au-delà d''un seuil de 1 000 €","Conserver les documents pendant 5 ans"]', 1, 'L''identification est obligatoire pour les opérations occasionnelles à partir de 1 000 €.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle autorité est chargée de la mise en œuvre des sanctions financières internationales (embargos) en France ?', '["La Direction générale du Trésor (DG Trésor)","L''Autorité de contrôle prudentiel et de résolution (ACPR)","La cellule de renseignement financier Tracfin"]', 0, 'La DG Trésor est l''autorité compétente pour appliquer les sanctions financières.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre un embargo et une mesure de gel des avoirs ?', '["L''embargo est décidé par l''UE, le gel des avoirs par la France","Le gel des avoirs est une mesure préventive, l''embargo une mesure répressive","L''embargo concerne des biens ou secteurs, le gel des avoirs vise des personnes ou entités"]', 2, 'L''embargo cible des biens ou secteurs, le gel des avoirs cible des personnes ou entités.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'À quelle autorité une société de gestion doit-elle déclarer une opération suspecte dans le cadre de la LCB-FT ?', '["Le procureur de la République","Tracfin","L''AMF"]', 1, 'Les professionnels assujettis doivent déclarer toute opération suspecte à Tracfin, la cellule de renseignement financier.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel seuil de détention du capital ou des droits de vote caractérise un bénéficiaire effectif au sens de la LCB-FT ?', '["10 %","25 %","50 %"]', 1, 'Le bénéficiaire effectif est toute personne détenant plus de 25 % du capital ou des droits de vote.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une mesure de gel des avoirs édictée dans le cadre d''un embargo sur les fonds d''une personne désignée ?', '["Ils sont transférés sous séquestre judiciaire","Ils sont confisqués au profit de l''État","Ils sont bloqués et ne peuvent faire l''objet d''aucune transaction"]', 2, 'Le gel des avoirs interdit tout mouvement de fonds sans transfert de propriété.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle est la durée maximale de report de la publication d''une information privilégiée par un émetteur ?', '["Aucune durée maximale, mais l''émetteur doit en informer l''autorité compétente","2 jours ouvrés maximum, sans condition","10 jours de bourse maximum, sous réserve de l''accord de l''AMF"]', 0, 'Le report est possible sans durée fixe si les conditions de confidentialité sont remplies et l''autorité informée.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la procédure de déclaration des transactions des dirigeants (PDMR) selon MAR ?', '["Ils doivent déclarer à l''émetteur uniquement dans les 10 jours ouvrés","Ils doivent déclarer à l''émetteur et à l''AMF dans les 3 jours ouvrés","Ils doivent déclarer à l''AMF dans les 5 jours ouvrés, sans informer l''émetteur"]', 1, 'Le PDMR notifie à l''émetteur et à l''autorité compétente dans un délai de 3 jours ouvrés après la transaction.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle pratique constitue une manipulation de marché par ''spoofing'' ?', '["Exécuter des ordres pour le compte de clients en respectant les règles","Publier des recherches sur une société sans conflit d''intérêts","Passer des ordres sans intention de les exécuter pour donner une fausse indication de la demande"]', 2, 'Le spoofing consiste à afficher des ordres non sincères pour tromper les autres participants sur le carnet d''ordres.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Qu''est-ce qu''une manipulation de marché par diffusion d''informations fausses ou trompeuses ?', '["Donner des informations exactes mais tardives","Diffuser des informations inexactes pour influencer le cours d''un instrument financier","Publier des informations réglementées conformément à la réglementation"]', 1, 'La diffusion d''informations inexactes ou trompeuses qui induit le marché en erreur constitue une manipulation de marché.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, un émetteur doit diffuser une information privilégiée au public :', '["dès que possible","après validation par l''AMF","dans un délai de 24 heures"]', 0, 'L''article 17 du règlement MAR impose une diffusion immédiate de l''information privilégiée.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle pratique est considérée comme une manipulation de marché au sens du règlement MAR ?', '["Utiliser une information privilégiée pour acheter des titres","Passer des ordres sans intention de les exécuter","Publier des états financiers annuels"]', 1, 'Le spoofing, ordres sans intention d''exécution, est une manipulation de marché interdite.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle pratique de manipulation de marché consiste à passer des ordres d''achat et de vente sur le même instrument pour créer une activité artificielle ?', '["Spoofing","Pump and dump","Wash trading"]', 2, 'Le wash trading simule des transactions pour donner une fausse impression de liquidité.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le délai maximal pour qu''une personne exerçant des responsabilités dirigeantes notifie ses transactions à l''autorité compétente ?', '["1 jour ouvrable","3 jours ouvrables","5 jours ouvrables"]', 1, 'Selon le règlement MAR, la notification doit intervenir dans les trois jours ouvrables suivant la transaction.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Selon le règlement MAR, quelle condition doit remplir une information pour être considérée comme privilégiée ?', '["Être précise, non publique et susceptible d''influencer le cours","Être publique et susceptible d''influencer le cours","Être précise et publique"]', 0, 'Une information privilégiée doit être précise, non rendue publique et susceptible d''influencer le cours des instruments financiers.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Qu''est-ce qu''une opération de wash trade dans le cadre des manipulations de marché ?', '["Achat et vente simultanés d''un même instrument par le même intervenant","Achat d''un instrument pour influencer le cours","Vente d''un instrument sans détention préalable"]', 0, 'Le wash trade consiste à acheter et vendre le même instrument simultanément pour créer une fausse apparence de liquidité.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Pour évaluer l''adéquation d''un instrument financier à un client, un prestataire de services d''investissement doit recueillir des informations sur :', '["les connaissances, l''expérience, la situation financière et les objectifs d''investissement du client.","uniquement les connaissances et l''expérience du client.","uniquement la situation financière et les objectifs d''investissement."]', 0, 'L''adéquation requiert une évaluation complète du profil du client, incluant tous ces éléments.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de commercialisation de produits d''épargne, quel document doit être remis à un client non professionnel avant la souscription d''un produit d''investissement packagé (PRIIP) ?', '["Le prospectus complet approuvé par l''Autorité des marchés financiers.","Le document d''informations clés (DIC) qui présente les caractéristiques essentielles et les risques du produit.","Un rapport annuel de gestion du produit."]', 1, 'Le DIC est obligatoire pour les PRIIPs, remis avant la souscription.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Un ordre à cours limité d''achat de 100 actions à 50 euros est placé. Le cours de l''action est actuellement de 52 euros. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement au cours de 52 euros.","L''ordre reste en attente jusqu''à ce que le cours atteigne 50 euros ou moins.","L''ordre est annulé automatiquement."]', 1, 'Un ordre à cours limité n''est exécuté qu''au prix limite ou meilleur.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Pour un client de détail, quel critère est prépondérant dans l''obligation de meilleure exécution ?', '["Le coût total de la transaction.","La rapidité d''exécution.","La probabilité d''exécution."]', 0, 'Pour les clients de détail, le coût total est le critère le plus important.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la commercialisation d''instruments financiers, quelle est l''obligation principale d''un conseiller en investissements financiers (CIF) ?', '["Vérifier l''adéquation de l''instrument au profil de l''investisseur","Garantir la performance de l''instrument","Transmettre systématiquement les ordres au marché"]', 0, 'Le CIF doit effectuer une évaluation de l''adéquation (suitability) avant toute recommandation.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Lors de la commercialisation d''un OPCVM, quel document doit être remis à l''investisseur avant la souscription ?', '["Le prospectus complet","Le document d''information clé pour l''investisseur (DICI)","Le rapport annuel de gestion"]', 1, 'Le DICI est obligatoire avant souscription, le prospectus est disponible mais pas systématiquement remis.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre d''achat à cours limité est exécuté uniquement si le prix du marché est :', '["supérieur ou égal au prix limite","strictement supérieur au prix limite","inférieur ou égal au prix limite"]', 2, 'Pour un achat, l''exécution n''a lieu que si le prix est au plus égal au prix limite.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Selon MIFID II, quelle est l''obligation principale d''un distributeur dans le cadre de la gouvernance produit ?', '["Ne distribuer que des produits à faible risque.","Définir un marché cible et s''assurer que le produit est distribué en cohérence avec celui-ci.","S''assurer que le produit est rentable pour le distributeur."]', 1, 'La gouvernance produit impose de définir un marché cible et de vérifier la cohérence de la distribution.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la règle concernant les rétrocessions (inducements) dans le cadre de la commercialisation de fonds ?', '["Elles sont interdites sauf si elles améliorent la qualité du service et sont divulguées.","Elles sont autorisées sans condition.","Elles sont interdites pour tous les clients."]', 0, 'Les rétrocessions sont permises si elles améliorent la qualité et sont transparentes.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre le test d''adéquation (suitability) et le test d''appropriation (appropriateness) ?', '["Le test d''appropriation est plus complet que le test d''adéquation.","Les deux tests sont obligatoires pour le service d''exécution seule.","Le test d''adéquation évalue la situation financière et les objectifs, tandis que l''appropriation ne vérifie que connaissances et expérience."]', 2, 'Le test d''adéquation est plus complet, incluant situation financière et objectifs.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''une entreprise d''investissement en matière de gestion des conflits d''intérêts ?', '["Elle doit les identifier et les prévenir, et informer le client si elle ne peut les éviter.","Elle doit les ignorer si le client est professionnel.","Elle doit les déclarer à l''AMF avant toute transaction."]', 0, 'L''entreprise doit prévenir les conflits et informer le client si elle ne peut les éviter.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quel est l''effet d''un ordre à cours limité par rapport à un ordre au marché ?', '["Il garantit l''exécution au prix indiqué ou meilleur.","Il ne garantit pas l''exécution si le prix n''est pas atteint.","Il est exécuté immédiatement au meilleur prix disponible."]', 1, 'Un ordre à cours limité ne garantit pas l''exécution si le prix n''est pas atteint.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation, quelle est l''obligation d''une entreprise d''investissement concernant l''évaluation de l''adéquation d''un service de conseil en investissement ?', '["Elle doit s''assurer que le client a les moyens financiers suffisants.","Elle doit fournir un rapport annuel sur les performances.","Elle doit recueillir des informations sur les connaissances et l''expérience du client en matière d''investissement."]', 2, 'L''évaluation d''adéquation exige de connaître les connaissances et l''expérience du client.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la conséquence d''un ordre ''tout ou rien'' ?', '["Il doit être exécuté en totalité ou pas du tout.","Il peut être exécuté partiellement.","Il est exécuté au prix du marché."]', 0, 'Un ordre tout ou rien ne peut être exécuté que si la totalité de la quantité est disponible.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Lors de la réception d''un ordre de bourse, quelle obligation incombe à l''entreprise d''investissement ?', '["Enregistrer l''ordre immédiatement et le transmettre sans délai","Ne transmettre l''ordre qu''après confirmation écrite du client","Transmettre l''ordre uniquement si le client a un compte espèces approvisionné"]', 0, 'Les ordres doivent être enregistrés et transmis sans délai pour garantir la meilleure exécution.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle information doit obligatoirement figurer dans le relevé de compte périodique envoyé au client ?', '["La valorisation des instruments financiers au prix de revient","Le détail des frais et commissions prélevés sur la période","La liste des ordres passés par le client sur les cinq dernières années"]', 1, 'Le relevé doit mentionner les frais et commissions pour assurer la transparence des coûts.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client donne un ordre à cours limité d''achat à 50 €, alors que le cours est de 52 €. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement au cours de 52 €","L''ordre est enregistré et ne sera exécuté que si le cours atteint 50 € ou moins","L''ordre est rejeté car le prix limite est inférieur au cours actuel"]', 1, 'Un ordre à cours limité n''est exécuté qu''au prix limite ou meilleur, donc il attend une baisse du cours.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la gestion de portefeuille, quelle obligation incombe à la société de gestion envers son client ?', '["Recueillir des informations sur la situation financière, les objectifs et la tolérance au risque","Se contenter d''une déclaration du client sans vérification","Ne pas demander d''informations si le client est professionnel"]', 0, 'La société de gestion doit évaluer l''adéquation en recueillant ces informations.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la caractéristique d''un ordre à cours limité ?', '["Il garantit l''exécution immédiate au prix du marché","Il est exécuté au prix indiqué ou à un prix plus favorable","Il est exécuté uniquement si le prix atteint le niveau indiqué"]', 1, 'Un ordre à cours limité est exécuté au prix indiqué ou à un prix plus favorable, sans garantie d''exécution.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Que signifie l''obligation de ''meilleure exécution'' pour un prestataire de services d''investissement ?', '["Exécuter les ordres dans l''ordre chronologique de réception","Négocier uniquement sur les marchés réglementés","Obtenir le meilleur résultat possible en considérant prix, coûts, rapidité et probabilité"]', 2, 'La meilleure exécution exige de prendre en compte plusieurs critères pour obtenir le meilleur résultat pour le client.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle caractéristique distingue un security token d''un utility token ?', '["Le security token confère des droits financiers ou de gouvernance sur un actif sous-jacent","Le utility token est toujours émis par une autorité publique","Le security token ne peut être échangé que sur des plateformes régulées"]', 0, 'Un security token représente un investissement et donne des droits économiques, contrairement à un utility token qui donne accès à un service.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le principal risque d''un stablecoin adossé à des réserves de monnaie fiduciaire ?', '["La volatilité de la crypto-monnaie sous-jacente","La défaillance du dépositaire ou la non-vérification des réserves","L''absence de réglementation sur les échanges"]', 1, 'Le risque réside dans la confiance en la détention effective des réserves, car une couverture insuffisante peut entraîner une perte de parité.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la tokenisation d''un actif immobilier, que représente le jeton émis ?', '["Une unité de compte virtuelle sans valeur légale","Une fraction de propriété de l''actif sous-jacent","Un simple moyen de paiement pour l''achat de l''actif"]', 1, 'La tokenisation fractionne la propriété d''un actif réel en jetons, chacun représentant une part de cet actif.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence directe de la forte volatilité des crypto-actifs sur leur utilisation comme monnaie ?', '["Ils deviennent plus attractifs pour les transactions quotidiennes","Leur valeur de référence instable rend difficile leur fonction d''unité de compte","Ils sont automatiquement indexés sur l''inflation"]', 1, 'Une monnaie doit être stable pour servir de mesure de valeur ; la volatilité compromet cette fonction.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Comment calcule-t-on la capitalisation boursière d''un crypto-actif ?', '["Prix × offre en circulation","Prix × offre totale","Prix × volume échangé"]', 0, 'La capitalisation boursière est le produit du prix par l''offre en circulation.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale distinction entre un security token et un utility token ?', '["Le security token est soumis à MiCA, l''utility token en est exempt","Le security token confère des droits financiers, l''utility token donne accès à un service","Le security token est émis sur une blockchain privée, l''utility token sur une blockchain publique"]', 1, 'Un security token représente un investissement, tandis qu''un utility token donne accès à un produit ou service.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la différence fondamentale entre une ''coin'' et un ''token'' dans l''écosystème crypto ?', '["Une coin est fongible, un token est non fongible","Une coin est une monnaie légale, un token est une monnaie privée","Une coin possède sa propre blockchain, un token utilise une blockchain existante"]', 2, 'Les coins ont leur propre blockchain, les tokens sont émis sur des blockchains existantes.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un DEX, quel mécanisme détermine le prix d''un actif dans un pool de liquidité ?', '["La formule du produit constant (x*y=k)","Le carnet d''ordres centralisé de l''exchange","Le prix moyen pondéré des transactions passées"]', 0, 'La formule x*y=k maintient l''équilibre des réserves et détermine le prix.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale caractéristique d''un jeton utilitaire (utility token) ?', '["Il confère des droits de propriété sur l''entreprise","Il donne accès à un service ou une fonctionnalité","Il est adossé à une monnaie fiduciaire"]', 1, 'Un utility token est conçu pour donner accès à un produit ou service.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle d''un oracle dans un smart contract ?', '["Il exécute automatiquement les transactions","Il sécurise le portefeuille de l''utilisateur","Il fournit des données externes au contrat"]', 2, 'Un oracle relie la blockchain aux données du monde réel.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le principe fondamental de la séparation des actifs dans un compte de tiers ?', '["Les actifs sont confondus avec ceux de la société de gestion.","Les actifs sont conservés par un dépositaire distinct.","Les actifs sont gérés par le dépositaire."]', 1, 'La séparation des actifs impose un dépositaire distinct pour protéger les investisseurs.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un FCP, qui est responsable de la valorisation des actifs ?', '["La société de gestion.","Le dépositaire.","L''auditeur."]', 0, 'La société de gestion est responsable de la valorisation, sous contrôle du dépositaire.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un ordre de souscription reçu après l''heure limite de centralisation ?', '["Il est exécuté au prix du jour même.","Il est annulé.","Il est exécuté au prix du jour suivant."]', 2, 'Les ordres reçus après l''heure limite sont traités sur la valeur liquidative suivante.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle principal d''un dépositaire dans la gestion collective ?', '["Gérer les investissements du fonds.","Conserver les actifs et contrôler la régularité des décisions.","Fixer la valeur liquidative."]', 1, 'Le dépositaire conserve les actifs et veille à la conformité des décisions de gestion.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un OPCVM indiciel, quel est l''impact d''une frais de gestion élevée sur la performance nette par rapport à l''indice de référence ?', '["Elle améliore la performance nette si l''indice monte","Elle réduit la performance nette, même si l''indice est stable","Elle n''a aucun impact si l''indice est volatil"]', 1, 'Les frais de gestion sont prélevés en permanence, réduisant la performance nette quel que soit le mouvement de l''indice.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un compte de tiers géré par un dépositaire central (par exemple Euroclear) est utilisé principalement pour :', '["Détenir des titres pour le compte d''autres dépositaires ou teneurs de compte","Enregistrer les transactions des investisseurs particuliers","Gérer les ordres de bourse des sociétés de gestion"]', 0, 'Le compte de tiers permet au dépositaire central de détenir des titres pour le compte d''intermédiaires financiers.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans une SICAV, la valeur liquidative (VL) est calculée en divisant l''actif net par le nombre de parts. Que se passe-t-il si des souscriptions importantes arrivent après le calcul de la VL ?', '["Les nouvelles souscriptions sont traitées à la VL du jour suivant","Les nouvelles souscriptions sont traitées à la VL du jour même","Les souscriptions sont suspendues jusqu''à la prochaine VL"]', 0, 'Les ordres reçus après la centralisation sont exécutés à la prochaine VL, conformément au principe de l''exécution à cours inconnu.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans la gestion collective, quel est le rôle principal du compte de tiers ?', '["Isoler les actifs des investisseurs de ceux de la société de gestion","Permettre des opérations de prêt de titres aux investisseurs","Garantir un rendement minimal aux porteurs de parts"]', 0, 'Le compte de tiers assure la ségrégation des actifs, protégeant les investisseurs en cas de faillite de la société de gestion.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est une obligation du dépositaire d''un OPCVM ?', '["Fixer la valeur liquidative chaque jour","Assurer la conservation des actifs et le contrôle de la régularité des décisions","Commercialiser les parts auprès des investisseurs"]', 1, 'Le dépositaire a une double mission de conservation et de contrôle, distincte de la gestion et de la commercialisation.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la limite maximale de détention d''un même émetteur pour un OPCVM de droit français ?', '["5% de l''actif","10% de l''actif","20% de l''actif"]', 2, 'La réglementation limite à 10% de l''actif la détention de titres d''un même émetteur pour un OPCVM.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle affirmation concernant un ordre à cours limité est exacte ?', '["Il garantit le prix mais pas l''exécution","Il garantit l''exécution mais pas le prix","Il garantit à la fois le prix et l''exécution"]', 0, 'Un ordre à cours limité s''exécute uniquement au prix indiqué ou meilleur, sans garantie d''exécution.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Comment est calculé un indice pondéré par la capitalisation ?', '["En donnant un poids égal à chaque action","En pondérant par la valeur de marché des titres","En pondérant par le volume de transactions"]', 1, 'Un indice pondéré par la capitalisation donne un poids proportionnel à la valeur boursière de chaque titre.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une augmentation de la liquidité sur la fourchette de prix (spread) ?', '["Elle élargit le spread","Elle réduit le spread","Elle n''a aucun effet sur le spread"]', 2, 'Une liquidité accrue resserre le spread, car le coût de transaction diminue.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Selon l''hypothèse d''efficience des marchés, quelle affirmation est vraie ?', '["Les cours reflètent toute l''information disponible","Les cours sont influencés par les rumeurs","Les cours sont déterminés par les fondamentaux uniquement"]', 0, 'L''efficience informationnelle implique que les prix intègrent instantanément toute information pertinente.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle d''une contrepartie centrale (CCP) dans un marché organisé ?', '["Elle fixe les prix d''équilibre lors de l''ouverture","Elle garantit la bonne fin des transactions en se substituant aux parties","Elle surveille les abus de marché en analysant les ordres"]', 1, 'La CCP s''interpose entre acheteurs et vendeurs pour garantir l''exécution des transactions.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre d''achat à cours limité est exécuté si le prix du marché est...', '["inférieur ou égal au prix limite","supérieur ou égal au prix limite","exactement égal au prix limite"]', 0, 'Un ordre à cours limité d''achat ne s''exécute qu''à un prix inférieur ou égal à la limite fixée.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un marché dirigé par les ordres, le carnet d''ordres central sert à...', '["enregistrer les transactions hors marché","surveiller les positions des membres","apparier les ordres d''achat et de vente selon des règles de priorité"]', 2, 'Le carnet d''ordres central est le mécanisme de confrontation des ordres qui détermine les prix.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un ordre d''achat à cours limité dont le prix est supérieur au meilleur prix vendeur ?', '["Il est exécuté immédiatement au meilleur prix vendeur","Il reste en carnet d''ordres en attente","Il est exécuté au prix limite"]', 0, 'Un ordre d''achat à cours limité au-dessus du meilleur vendeur est exécutable immédiatement au meilleur prix disponible.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un système de négociation avec fixing, comment est déterminé le prix d''équilibre ?', '["Par le dernier prix négocié","Par le prix qui maximise le volume d''ordres exécutés","Par la moyenne des prix limites"]', 1, 'Le fixing détermine le prix qui maximise le volume d''ordres exécutés, équilibrant offre et demande.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un indice à pondération égale (equal weight) accorde à chaque composant...', '["Un poids proportionnel à sa capitalisation","Un poids inversement proportionnel à sa volatilité","Un poids identique"]', 2, 'Dans un indice à pondération égale, chaque action a le même poids, indépendamment de sa capitalisation.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''objectif principal du mécanisme de livraison contre paiement (DVP) dans le règlement-livraison ?', '["Éliminer le risque de principal","Réduire les frais de transaction","Accélérer la vitesse de règlement"]', 0, 'Le DVP lie la livraison des titres au paiement, supprimant le risque de principal.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans l''Union européenne, quel est le délai standard de règlement-livraison pour les transactions sur titres ?', '["J+1","J+2","J+3"]', 1, 'Depuis 2014, le règlement-livraison standard est de T+2 jours ouvrés.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle d''une contrepartie centrale (CCP) dans une opération de marché ?', '["Elle fournit des services de conservation de titres","Elle fixe les prix des instruments financiers","Elle garantit la bonne fin des transactions en devenant acheteur et vendeur"]', 2, 'La CCP s''interpose entre les parties, devenant contrepartie de chacune, réduisant le risque de contrepartie.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale caractéristique de TARGET2-Securities (T2S) ?', '["C''est un système de règlement-livraison de titres en monnaie de banque centrale","C''est un système de compensation multilatérale","C''est un système de négociation d''actions"]', 0, 'T2S est une plateforme de règlement-livraison de titres en monnaie de banque centrale.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet principal de la compensation multilatérale sur les transactions de gré à gré ?', '["Elle réduit le nombre de transactions à régler en nettant les positions.","Elle augmente le risque de contrepartie en multipliant les expositions.","Elle élimine tout besoin de garanties pour les membres."]', 0, 'La compensation nette les obligations réciproques, réduisant ainsi le volume des règlements.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un système de règlement-livraison, que garantit le principe de livraison contre paiement (DVP) ?', '["Que les titres sont livrés avant le paiement, avec un délai de grâce.","Que le transfert de titres et le paiement sont simultanés et irrévocables.","Que le paiement est effectué avant la livraison, sans condition."]', 1, 'Le DVP assure la simultanéité des deux flux, éliminant le risque principal.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle principal d''une contrepartie centrale (CCP) dans une opération de marché ?', '["Elle agit comme un simple intermédiaire sans assumer de risque.","Elle garantit uniquement la livraison des titres, pas le paiement.","Elle se substitue aux deux parties, devenant l''acheteur et le vendeur."]', 2, 'La CCP s''interpose entre les parties, assumant le risque de contrepartie.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le processus de règlement-livraison, quel est le rôle principal d''un dépositaire central ?', '["Garantir la contrepartie en cas de défaut","Conserver les titres et assurer leur transfert","Fixer les prix des transactions"]', 1, 'Le dépositaire central détient les titres et facilite leur transfert lors du règlement.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un défaut de paiement d''un membre compensateur auprès d''une chambre de compensation ?', '["La chambre annule toutes les transactions du membre","La chambre utilise le fonds de garantie pour couvrir les pertes","La chambre transfère les positions à un autre membre sans frais"]', 1, 'Le fonds de garantie mutualisé sert à absorber les pertes en cas de défaut d''un membre.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'En Europe, le délai standard de règlement-livraison pour les actions est de combien de jours après la date de transaction ?', '["T+1","T+2","T+3"]', 1, 'Le règlement-livraison standard est T+2 pour les actions sur les marchés européens.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital par émission de droits préférentiels de souscription, un actionnaire qui ne souhaite pas souscrire peut-il vendre ses droits ?', '["Oui, les droits sont négociables sur le marché pendant la période de souscription","Non, les droits sont obligatoirement exercés ou perdus","Oui, mais uniquement auprès de la société émettrice"]', 0, 'Les droits préférentiels de souscription sont des titres négociables et peuvent être cédés sur le marché.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une division de la valeur nominale d''une action (split) sur le capital social d''une société ?', '["Le capital social augmente proportionnellement","Le capital social reste inchangé","Le capital social diminue en raison des frais"]', 1, 'Un split modifie le nombre d''actions mais pas le montant total du capital social.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre d''une émission obligataire à taux variable, le coupon est généralement indexé sur quel type de taux ?', '["Un taux fixe déterminé à l''émission","Un taux de référence du marché monétaire ou obligataire","Le taux de rendement des actions de l''émetteur"]', 1, 'Le coupon variable est révisé périodiquement selon un taux de référence comme l''Euribor ou l''OAT.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une offre publique de rachat (OPR) réussie sur le flottant d''une société cotée ?', '["Le flottant augmente car les actions sont redistribuées","Le flottant diminue car l''initiateur détient une part plus importante","Le flottant reste identique car les actions sont annulées"]', 1, 'L''OPR réduit le nombre d''actions en circulation hors de l''initiateur, donc le flottant baisse.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital avec maintien du droit préférentiel de souscription, le prix d''émission des actions nouvelles est généralement...', '["supérieur au cours de bourse","inférieur au cours de bourse","égal au cours de bourse"]', 1, 'Le prix d''émission est fixé en dessous du cours de bourse pour inciter les actionnaires à exercer leurs droits.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une augmentation de capital par incorporation de réserves sur le nombre d''actions ?', '["Le nombre d''actions augmente","Le nombre d''actions diminue","Le nombre d''actions reste inchangé"]', 0, 'L''incorporation de réserves émet de nouvelles actions gratuites, augmentant le nombre d''actions sans modification du capital.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors de l''émission d''une obligation à taux fixe, si le taux de marché est inférieur au taux nominal, le prix d''émission sera...', '["inférieur au pair","égal au pair","supérieur au pair"]', 2, 'Pour compenser un taux nominal supérieur, l''obligation est émise avec une prime, donc au-dessus du pair.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital avec droit préférentiel de souscription (DPS), quel est l''effet immédiat pour un actionnaire existant qui ne souscrit pas ?', '["Il reçoit une compensation en espèces équivalente à la valeur du DPS","Il subit une dilution de sa participation, mais peut vendre ses DPS pour compenser","Il conserve automatiquement sa part si le nombre d''actions est inchangé"]', 1, 'Sans souscription, la part relative diminue, mais la vente des DPS compense partiellement la dilution.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un split (division du nominal) sur le capital social d''une société ?', '["Le capital social augmente proportionnellement au nombre de nouvelles actions","Le capital social reste inchangé, mais le nombre d''actions augmente","Le capital social diminue car la valeur nominale est réduite"]', 1, 'Un split modifie le nombre d''actions et le nominal, mais le capital social total reste identique.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans une OPA (offre publique d''achat), quel est le rôle de l''AMF ?', '["Elle fixe le prix d''achat des titres visés","Elle garantit le succès de l''offre en achetant les titres non apportés","Elle contrôle la régularité et l''information diffusée pendant l''offre"]', 2, 'L''AMF supervise la transparence et le respect des règles, sans fixer le prix ni garantir l''offre.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le bilan comptable, quelle relation fondamentale est toujours vérifiée ?', '["Actif = Passif - Capitaux propres","Actif = Passif + Capitaux propres","Actif + Passif = Capitaux propres"]', 1, 'L''équation fondamentale du bilan est Actif = Passif + Capitaux propres.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre le résultat comptable et la trésorerie nette ?', '["Le résultat inclut les charges non décaissées comme les amortissements","La trésorerie inclut les produits non encaissés","Ils sont toujours identiques"]', 0, 'Le résultat comptable intègre des charges calculées sans sortie de trésorerie, contrairement à la trésorerie.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une dotation aux amortissements sur le résultat et la trésorerie ?', '["Diminue le résultat et diminue la trésorerie","Augmente le résultat et n''affecte pas la trésorerie","Diminue le résultat mais n''affecte pas la trésorerie"]', 2, 'L''amortissement est une charge non décaissée : il réduit le résultat sans impact sur la trésorerie.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Le ratio de liquidité générale se calcule comme :', '["Trésorerie / Passif circulant","Actif circulant / Passif circulant","Capitaux propres / Total du bilan"]', 1, 'La liquidité générale compare l''actif circulant au passif circulant pour mesurer la solvabilité à court terme.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Une entreprise acquiert une machine pour 20 000 €, sans valeur résiduelle, amortissable sur 4 ans en linéaire. Quel est l''amortissement annuel ?', '["4 000 €","5 000 €","6 000 €"]', 1, 'L''amortissement linéaire se calcule en divisant le coût par la durée d''utilisation : 20 000 / 4 = 5 000 €.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Si une entreprise allonge le délai de paiement accordé à ses clients, quel est l''effet sur son besoin en fonds de roulement (BFR) ?', '["Le BFR diminue","Le BFR reste inchangé","Le BFR augmente"]', 2, 'L''allongement du délai client accroît les créances, donc le BFR augmente.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ratio de liquidité générale inférieur à 1 indique que :', '["L''entreprise dispose d''un excédent de trésorerie","L''actif à court terme ne couvre pas le passif à court terme","L''entreprise est en situation de cessation de paiement"]', 1, 'Un ratio inférieur à 1 signifie que les dettes à court terme excèdent les actifs à court terme.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une augmentation des amortissements sur le résultat net d''une entreprise ?', '["Diminue le résultat net","Augmente le résultat net","N''a aucun effet"]', 0, 'Les amortissements sont des charges qui réduisent le résultat net.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le bilan comptable, le fonds de roulement net global (FRNG) se calcule par :', '["Capitaux propres - Actif immobilisé","Actif circulant - Passif circulant","Trésorerie nette - Dettes financières"]', 1, 'Le FRNG est la différence entre l''actif circulant et le passif circulant.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une augmentation du besoin en fonds de roulement (BFR) sur la trésorerie d''une entreprise ?', '["La trésorerie augmente","La trésorerie reste inchangée","La trésorerie diminue"]', 2, 'Une hausse du BFR nécessite un financement supplémentaire, réduisant la trésorerie.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle autorité délivre l''agrément aux sociétés de gestion de portefeuille en France ?', '["L''AMF","L''ACPR","L''ESMA"]', 0, 'L''AMF est l''autorité compétente pour agréer les sociétés de gestion en France.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MiFID II, quelle est la durée minimale de conservation des enregistrements des ordres et transactions par les prestataires de services d''investissement ?', '["3 ans","5 ans","10 ans"]', 1, 'MiFID II impose une conservation d''au moins 5 ans pour ces enregistrements.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale mission de l''ESMA en matière de supervision ?', '["Coordonner la surveillance des agences de notation et des infrastructures de marché","Superviser directement les banques systémiques","Fixer les taux d''intérêt de la zone euro"]', 0, 'L''ESMA coordonne la supervision des agences de notation et des infrastructures de marché.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre de bourse ''à la meilleure limite'' est un ordre qui :', '["est exécuté au prix du marché dès réception","est exécuté au meilleur prix disponible dans le carnet d''ordres","est exécuté uniquement si le prix atteint une limite"]', 1, 'Un ordre à la meilleure limite est exécuté au meilleur prix disponible dans le carnet d''ordres.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement Prospectus, quelle est la durée de validité d''un prospectus approuvé par l''AMF ?', '["6 mois","12 mois","24 mois"]', 1, 'Le prospectus est valable 12 mois après approbation, sous réserve de modifications.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MiFID II, quelle est la durée minimale de conservation des enregistrements téléphoniques par les entreprises d''investissement ?', '["3 ans","7 ans","5 ans"]', 2, 'MiFID II impose une conservation de 5 ans, extensible à 7 ans sur demande.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet du passeport européen pour un OPCVM agréé en France ?', '["Il permet sa commercialisation dans tous les États membres sans agrément local","Il exige un agrément dans chaque pays de commercialisation","Il ne s''applique qu''aux fonds alternatifs"]', 0, 'Le passeport européen autorise la libre commercialisation des OPCVM dans l''UE après notification.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle autorité est chargée de la surveillance prudentielle des établissements de crédit en France ?', '["L''ACPR","L''AMF","L''ESMA"]', 0, 'L''ACPR assure la surveillance prudentielle des banques et assurances.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MiFID II, quelle obligation incombe aux entreprises d''investissement pour l''exécution des ordres clients ?', '["Garantir le prix le plus bas","Prendre toutes les mesures suffisantes pour obtenir le meilleur résultat possible","Exécuter sur le marché principal"]', 1, 'MiFID II impose une obligation de meilleure exécution.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Que permet le passeport européen pour une société de gestion ?', '["Gérer des fonds sans agrément national","Éviter toute obligation de déclaration","Commercialiser des fonds dans l''UE sans agrément supplémentaire"]', 2, 'Le passeport permet de commercialiser des fonds dans l''UE sans nouvel agrément.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement général de l''AMF, quelle est la mission principale du responsable de la conformité et du contrôle interne (RCCI) ?', '["Veiller à la mise en œuvre des procédures de conformité et informer la direction des manquements.","Assurer la gestion des risques de crédit de l''entreprise.","Superviser les opérations de marché en temps réel."]', 0, 'Le RCCI est chargé de la conformité et du contrôle interne, notamment le suivi des procédures et le signalement des manquements.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de déontologie, quelle est l''obligation d''un prestataire de services d''investissement concernant les opérations personnelles de ses collaborateurs ?', '["Il doit déclarer ces opérations à l''AMF dans un délai de 5 jours ouvrés.","Il doit mettre en place un registre des opérations personnelles et le conserver pendant 5 ans.","Il doit interdire toute opération personnelle sur les instruments financiers."]', 1, 'Le prestataire doit tenir un registre des opérations personnelles et le conserver pendant 5 ans.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la lutte contre le blanchiment, quelle est la procédure applicable pour une déclaration de soupçon à Tracfin ?', '["La déclaration doit être faite par écrit dans un délai de 48 heures.","La déclaration est facultative si le montant est inférieur à 10 000 euros.","La déclaration doit être faite avant toute exécution de l''opération suspecte."]', 2, 'La déclaration de soupçon doit être faite avant l''exécution de l''opération suspecte.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la sanction maximale que l''AMF peut prononcer à l''encontre d''une société de gestion pour manquement à ses obligations de conformité ?', '["Une amende de 100 millions d''euros ou 10% du chiffre d''affaires annuel.","Une interdiction d''exercer pendant 10 ans.","Une radiation de la liste des sociétés de gestion."]', 0, 'L''AMF peut infliger une amende administrative de 100 millions d''euros maximum ou 10% du CA.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la sanction maximale encourue par une personne physique pour un délit d''initié selon le code monétaire et financier ?', '["5 ans d''emprisonnement et 500 000 euros d''amende","7 ans d''emprisonnement et 1 million d''euros d''amende","3 ans d''emprisonnement et 300 000 euros d''amende"]', 0, 'Le délit d''initié est puni de cinq ans d''emprisonnement et de 500 000 euros d''amende.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En France, la déclaration de franchissement de seuil de participation doit être adressée à l''AMF et à la société concernée dans un délai de...', '["5 jours ouvrés","4 jours de négociation","10 jours calendaires"]', 1, 'Le délai réglementaire est de quatre jours de négociation à compter du franchissement.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre d''achat à cours limité est exécuté...', '["uniquement au prix limite ou à un prix supérieur","à tout prix dès sa transmission","uniquement au prix limite ou à un prix inférieur"]', 2, 'Un ordre à cours limité ne peut être exécuté qu''au prix limite ou à un prix plus favorable.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Le rôle d''une chambre de compensation est de...', '["garantir la bonne fin des transactions en se substituant aux contreparties","fixer les cours de clôture des instruments financiers","contrôler les abus de marché sur les marchés réglementés"]', 0, 'La compensation centralisée réduit le risque de contrepartie en s''interposant entre acheteurs et vendeurs.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Un conseiller en investissements financiers (CIF) doit obligatoirement adhérer à une association agréée par l''AMF. Cette adhésion a pour objet principal de :', '["assurer sa responsabilité civile professionnelle","garantir sa formation continue","lui permettre de recevoir des fonds de ses clients"]', 0, 'L''adhésion à une association agréée est une condition d''exercice, elle vérifie notamment la couverture de la responsabilité civile professionnelle.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En France, les sociétés de gestion de portefeuille sont soumises au contrôle de l''AMF et de l''ACPR. Quel aspect relève spécifiquement de l''ACPR ?', '["Le respect des règles de conduite","La composition du portefeuille","La solidité financière"]', 2, 'L''ACPR contrôle la solidité financière, tandis que l''AMF contrôle le respect des règles de conduite.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre d''achat à cours limité de 50 € est passé alors que le cours est de 52 €. Que se produit-il ?', '["L''ordre est exécuté immédiatement au prix de 50 €","L''ordre reste en attente jusqu''à ce que le cours atteigne 50 € ou moins","L''ordre est exécuté immédiatement au prix de 52 €"]', 1, 'Un ordre à cours limité d''achat ne s''exécute qu''au prix limite ou en dessous, donc il reste en attente tant que le cours n''est pas ≤ 50 €.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la mission principale de l''Autorité des Marchés Financiers (AMF) ?', '["Assurer la stabilité du système financier dans son ensemble","Veiller à la protection de l''épargne investie et à la bonne information des investisseurs","Contrôler les risques systémiques des établissements de crédit"]', 1, 'L''AMF protège l''épargne investie et veille à l''information des investisseurs.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle autorité européenne est responsable de la surveillance directe des agences de notation ?', '["L''ESMA","L''AMF","L''ACPR"]', 0, 'L''ESMA a compétence exclusive pour agréer et surveiller les agences de notation dans l''UE.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle d''une contrepartie centrale (CCP) dans les transactions sur produits dérivés ?', '["Elle fixe les prix des instruments dérivés","Elle enregistre les transactions pour le compte de l''autorité de régulation","Elle garantit la performance des transactions en se substituant aux parties"]', 2, 'La CCP s''interpose entre acheteurs et vendeurs pour garantir l''exécution des transactions.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''une société de gestion concernant la fonction de conformité ?', '["Elle doit être indépendante et permanente, avec des moyens adaptés","Elle peut être externalisée sans contrôle de l''AMF","Elle est obligatoire uniquement pour les OPCVM"]', 0, 'La fonction de conformité doit être permanente, indépendante et disposer de moyens suffisants.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de transactions personnelles des collaborateurs, que doit faire une société de gestion ?', '["Interdire les transactions sur instruments financiers sans autorisation préalable","Autoriser toutes transactions si déclarées a posteriori","Ne pas surveiller les comptes des dirigeants"]', 0, 'Les transactions personnelles doivent être préalablement autorisées et surveillées.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un ordre à cours limité non exécuté ?', '["Il reste valide jusqu''à son annulation ou sa fin de validité","Il est automatiquement annulé en fin de séance","Il est transformé en ordre au marché"]', 0, 'Un ordre à cours limité reste actif tant qu''il n''est pas exécuté, annulé ou arrivé à échéance.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle pratique est considérée comme une manipulation de marché ?', '["Passer des ordres sans intention de les exécuter pour influencer le prix","Transmettre des ordres en respectant les règles de transparence","Négocier pour couvrir un risque de portefeuille"]', 0, 'Les ordres fictifs ou trompeurs visant à fausser le prix constituent une manipulation de marché.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation AMF, quelle est l''obligation d''un prestataire de services d''investissement en matière de gestion des conflits d''intérêts ?', '["Il doit les ignorer","Il doit les prévenir et les gérer","Il doit les déclarer à l''AMF"]', 1, 'Le PSI doit identifier, prévenir et gérer les conflits d''intérêts pour éviter de nuire aux clients.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la règle applicable aux incitations (inducements) reçues par un prestataire de services d''investissement ?', '["Elles sont interdites en toutes circonstances","Elles sont autorisées sans condition","Elles sont autorisées si elles sont révélées au client et ne portent pas atteinte à l''intérêt du client"]', 2, 'Les incitations doivent être transparentes et ne pas nuire à la qualité du service rendu au client.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de déontologie, quelle est l''obligation d''une entreprise d''investissement concernant les conflits d''intérêts ?', '["Elle doit les éviter totalement.","Elle doit les identifier, les prévenir ou les gérer, et informer le client si elle ne peut les éviter.","Elle doit les déclarer systématiquement à l''AMF."]', 1, 'La réglementation impose de gérer les conflits d''intérêts, et si le risque persiste, d''informer le client.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans une société de gestion, quelle est la fonction du responsable de la conformité et du contrôle interne (RCCI) ?', '["Il veille au respect des obligations réglementaires et à la mise en œuvre des procédures internes.","Il est chargé de la surveillance des risques financiers.","Il est responsable de la stratégie d''investissement."]', 0, 'Le RCCI a pour mission de garantir la conformité réglementaire et le contrôle interne.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Qu''est-ce que le principe de ''meilleure exécution'' (best execution) pour un prestataire de services d''investissement ?', '["Exécuter l''ordre au prix le plus bas possible.","Exécuter l''ordre en tenant compte de tous les facteurs (prix, coûts, rapidité, probabilité d''exécution) pour obtenir le meilleur résultat possible pour le client.","Exécuter l''ordre sur la plateforme de négociation la plus régulée."]', 1, 'La meilleure exécution est une obligation de résultat optimal pour le client, basée sur plusieurs critères.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de LCB-FT, quelle est l''obligation d''un professionnel après une déclaration de soupçon à Tracfin ?', '["Il doit informer le client de la déclaration.","Il lui est interdit d''informer le client de la déclaration.","Il doit suspendre toute opération pendant 48 heures."]', 1, 'Le secret professionnel est levé mais l''interdiction de divulgation au client s''applique.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Lorsqu''un établissement financier identifie une personne ou entité inscrite sur une liste de gel des avoirs, quelle est son obligation ?', '["Confisquer les avoirs au profit du Trésor public.","Restituer les avoirs après vérification de l''identité.","Geler les avoirs et informer l''autorité compétente."]', 2, 'Le gel des avoirs est immédiat et la déclaration à l''autorité est requise.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la LCB-FT, que signifie l''approche par les risques ?', '["Utiliser des modèles statistiques pour évaluer le risque de blanchiment.","Appliquer des mesures de vigilance proportionnées au niveau de risque du client.","Exiger des garanties supplémentaires pour tous les clients sans distinction."]', 1, 'L''approche par les risques adapte les mesures de vigilance selon le risque identifié.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la différence entre un embargo et des sanctions ciblées ?', '["Un embargo est une mesure générale contre un pays, les sanctions ciblées visent des personnes ou entités spécifiques.","Un embargo est une mesure temporaire, les sanctions ciblées sont permanentes.","Un embargo est décidé par l''ONU, les sanctions ciblées par l''UE."]', 0, 'L''embargo s''applique à un pays entier, les sanctions ciblées à des individus ou entités.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de gel des avoirs, quelle proposition est exacte ?', '["Le gel des avoirs s''applique uniquement aux comptes bancaires.","Le gel des avoirs interdit de mettre des fonds à disposition de la personne désignée.","Le gel des avoirs est une mesure facultative pour les sociétés de gestion."]', 1, 'Le gel des avoirs impose de ne pas mettre de fonds ou ressources économiques à disposition de la personne visée.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée de conservation des documents relatifs à la relation d''affaires en matière de LCB-FT ?', '["5 ans après la fin de la relation d''affaires.","10 ans après la fin de la relation d''affaires.","3 ans après la fin de la relation d''affaires."]', 0, 'Les documents doivent être conservés 5 ans après la fin de la relation d''affaires.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Comment une entreprise doit-elle vérifier si un client est soumis à un embargo ?', '["En demandant au client de signer une déclaration sur l''honneur.","En s''appuyant sur la réputation du client.","En consultant les listes publiées par l''ONU et l''UE."]', 2, 'La vérification repose sur la consultation des listes de sanctions financières publiées par l''ONU et l''UE.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée de conservation des documents relatifs à la relation d''affaires imposée par la réglementation LCB-FT ?', '["3 ans après la fin de la relation d''affaires","5 ans après la fin de la relation d''affaires","10 ans après la fin de la relation d''affaires"]', 1, 'La réglementation impose une conservation de 5 ans après la fin de la relation d''affaires.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un gel des avoirs ordonné par une résolution du Conseil de sécurité de l''ONU sur les fonds d''une personne désignée ?', '["Les fonds sont bloqués et toute opération est interdite","Les fonds sont confisqués au profit de l''État","Les fonds sont transférés sur un compte séquestre"]', 0, 'Le gel des avoirs interdit toute opération sur les fonds, sans confiscation.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une déclaration de soupçon sur l''exécution d''une opération ?', '["L''opération doit être exécutée immédiatement","L''opération est interdite définitivement","L''opération peut être différée pendant un délai maximal de 48 heures"]', 2, 'La déclaration de soupçon permet un différé d''exécution de 48 heures maximum.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle condition doit remplir une information pour être qualifiée de privilégiée ?', '["Être précise, non publique et susceptible d''influencer notablement le cours.","Être publique mais difficile à interpréter pour les investisseurs.","Être précise et publique, mais avec un impact potentiel sur le cours."]', 0, 'L''information privilégiée doit être précise, non rendue publique et avoir un impact potentiel significatif sur le cours.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''un émetteur en cas de retard dans la publication d''une information privilégiée ?', '["Il doit publier immédiatement, sans aucune exception.","Il peut reporter la publication sous sa propre responsabilité, sans condition.","Il doit informer l''AMF et peut reporter la publication si ses intérêts légitimes sont en jeu."]', 2, 'L''émetteur peut reporter la publication sous conditions, notamment en informant l''AMF et en préservant ses intérêts légitimes.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une manipulation de marché par diffusion de fausses informations sur le marché ?', '["Elle augmente la liquidité du titre concerné.","Elle fausse le mécanisme de formation des prix.","Elle réduit la volatilité du titre."]', 1, 'La diffusion de fausses informations induit les investisseurs en erreur et fausse les prix.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre annulé avant exécution peut-il constituer une manipulation de marché ?', '["Oui, s''il est utilisé pour donner une fausse indication de l''offre et de la demande.","Non, car aucune transaction n''a eu lieu.","Oui, uniquement s''il est répété plus de dix fois."]', 0, 'L''annulation d''ordres peut être une manipulation si elle vise à tromper le marché sur la liquidité.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle proposition est exacte concernant la notification des opérations des personnes exerçant des responsabilités dirigeantes ?', '["La notification doit être faite à l''AMF dans un délai de 3 jours ouvrés","La notification doit être faite uniquement à l''émetteur dans un délai de 5 jours ouvrés","La notification doit être faite à l''émetteur et à l''AMF dans un délai de 3 jours ouvrés"]', 2, 'Selon MAR, les dirigeants notifient à l''émetteur et à l''AMF dans les 3 jours ouvrés.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle proposition est exacte concernant la manipulation de marché ?', '["La manipulation de marché inclut la diffusion d''informations fausses ou trompeuses","La manipulation de marché ne concerne que les transactions sur actions","La manipulation de marché est uniquement sanctionnée si elle entraîne un profit"]', 0, 'La manipulation de marché comprend notamment la diffusion d''informations fausses ou trompeuses.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur détient une information privilégiée. Quelle proposition est exacte ?', '["Il peut négocier s''il attend 24 heures après la publication","Il lui est interdit de négocier tant que l''information n''est pas publiée","Il peut négocier si l''information est déjà publique dans un autre pays"]', 1, 'L''interdiction de négociation sur information privilégiée s''applique jusqu''à sa publication.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle est l''obligation d''un émetteur concernant une information privilégiée ?', '["La publier dès que possible, sauf report autorisé","La transmettre uniquement à l''AMF","La garder confidentielle pendant 30 jours"]', 0, 'L''émetteur doit publier sans délai l''information privilégiée, mais peut reporter la publication sous conditions.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la durée de la période de négociation pour les dirigeants avant la publication des résultats annuels selon le règlement MAR ?', '["15 jours ouvrés","60 jours calendaires","30 jours calendaires"]', 2, 'La période de négociation est de 30 jours calendaires avant la publication du rapport annuel.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre du conseil en investissement, quelle obligation incombe au conseiller vis-à-vis du client ?', '["Évaluer l''expérience et les connaissances du client uniquement si celui-ci le demande","Évaluer l''expérience et les connaissances du client et fournir un rapport de pertinence","Évaluer l''expérience et les connaissances du client uniquement pour les produits complexes"]', 1, 'Le conseiller doit évaluer les connaissances et l''expérience du client et fournir un rapport de pertinence avant de recommander un investissement.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MIFID II, quelles sont les conditions pour qu''un incitatif (commission) soit autorisé dans la commercialisation ?', '["Les incitatifs sont toujours interdits, quel que soit le contexte","Les incitatifs sont autorisés s''ils sont de faible valeur et non monétaires","Les incitatifs sont autorisés s''ils améliorent la qualité du service et sont divulgués au client"]', 2, 'Les incitatifs sont permis s''ils améliorent la qualité du service et sont clairement divulgués, conformément à MIFID II.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle caractéristique définit un ordre à cours limité ?', '["Il garantit l''exécution au prix limite ou à un prix meilleur, mais pas l''exécution elle-même","Il garantit l''exécution immédiate au prix du marché","Il garantit à la fois l''exécution et le prix limite"]', 0, 'Un ordre à cours limité fixe un prix maximal (achat) ou minimal (vente) mais ne garantit pas que l''ordre sera exécuté.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'En matière d''exécution des ordres, que signifie l''obligation de ''meilleure exécution'' pour une entreprise d''investissement ?', '["Obtenir systématiquement le prix le plus bas du marché","Prendre toutes les mesures suffisantes pour obtenir le meilleur résultat possible en considérant prix, coûts, rapidité et autres facteurs","Exécuter l''ordre au prix moyen du marché à un instant donné"]', 1, 'La meilleure exécution exige de considérer plusieurs facteurs (prix, coûts, vitesse, probabilité d''exécution) pour obtenir le meilleur résultat pour le client.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MIFID II, quelle est l''obligation d''une entreprise d''investissement lorsqu''elle fournit un service de conseil en investissement ?', '["Évaluer l''adéquation (suitability) et fournir un rapport sur l''adéquation","Évaluer uniquement la connaissance et l''expérience du client (appropriateness)","Vérifier que le client dispose de moyens financiers suffisants"]', 0, 'Le conseil en investissement exige un test d''adéquation et un rapport écrit.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans la commercialisation de produits financiers, quelle est la règle sur les incitations (rétrocessions) versées par un tiers ?', '["Elles sont interdites sauf si elles améliorent la qualité du service et sont divulguées","Elles sont autorisées sans condition si elles figurent au contrat","Elles sont autorisées uniquement si elles proviennent de l''émetteur du produit"]', 0, 'Les incitations ne sont permises que si elles améliorent la qualité du service et sont transparentes.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client passe un ordre à cours limité pour acheter une action à 50 € alors que le cours est de 52 €. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement à 50 €","L''ordre est enregistré et exécuté si le cours atteint 50 € ou moins","L''ordre est rejeté car le prix est inférieur au cours du marché"]', 1, 'Un ordre à cours limité n''est exécuté que si le marché atteint le prix limite ou mieux.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la commercialisation d''un instrument financier complexe à un client non professionnel, quelle est l''obligation de l''entreprise d''investissement ?', '["Réaliser un test d''adéquation (suitability) systématique avant toute transaction.","Réaliser un test de caractère approprié (appropriateness) avant la transaction.","S''abstenir de toute transaction si le client refuse de fournir des informations."]', 1, 'Pour les instruments complexes, un test d''appropriateness est requis, contrairement au suitability qui s''applique au conseil ou à la gestion de portefeuille.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de commercialisation d''instruments financiers, quelle proposition relative aux incitations (inducements) est exacte ?', '["Les incitations sont interdites en toutes circonstances.","Les incitations sont autorisées si elles améliorent la qualité du service et sont divulguées au client.","Les incitations sont autorisées si elles sont inférieures à 100 euros."]', 2, 'Les incitations sont permises si elles visent à améliorer la qualité du service et sont clairement divulguées, sans seuil monétaire fixe.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité est un ordre qui :', '["Garantit l''exécution au prix limite ou mieux.","Ne peut être exécuté que si le prix du marché atteint le prix limite.","Est exécuté au prix du marché dès réception."]', 0, 'L''ordre à cours limité n''est exécuté que si le marché atteint le prix limite ou un prix plus favorable, sans garantie d''exécution.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation, quelle obligation s''impose à un prestataire de services d''investissement lors de la recommandation d''un instrument financier à un client non professionnel ?', '["Évaluer l''adéquation (suitability)","Évaluer le caractère approprié (appropriateness)","Fournir une information neutre sur les risques"]', 0, 'Pour un conseil personnalisé, l''adéquation est obligatoire, contrairement à l''appropriateness pour les services sans conseil.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la relation client, qu''est-ce que le devoir de conseil impose au conseiller en investissements financiers ?', '["Proposer systématiquement les produits les plus rentables","Adapter ses recommandations au profil et aux objectifs du client","Garantir la performance des placements"]', 1, 'Le devoir de conseil exige une adaptation au profil du client, sans garantie de performance.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité est exécuté uniquement si le prix du marché atteint ou dépasse le prix limite. Quelle affirmation est exacte ?', '["Il garantit l''exécution au prix limite","Il peut ne pas être exécuté si le prix limite n''est pas atteint","Il est exécuté au meilleur prix disponible immédiatement"]', 1, 'L''ordre à cours limité n''est exécuté que si le marché atteint le prix limite, sinon il reste en attente.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Pour un ordre de grande taille, quel facteur prédomine dans la politique de meilleure exécution ?', '["La rapidité d''exécution","La probabilité d''exécution","Le coût total de la transaction"]', 2, 'Pour les ordres importants, le coût total (frais, prix, impact) est le critère déterminant.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la directive MIF 2, quelle obligation s''impose à un prestataire de services d''investissement lors de la fourniture d''un service de conseil en investissement ?', '["Obtenir l''accord écrit du client pour chaque transaction","Évaluer l''adéquation du service au profil du client","Fournir une information claire sur les coûts et charges"]', 1, 'Le conseil en investissement exige une évaluation de l''adéquation (suitability) pour recommander des instruments adaptés.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée minimale de conservation des enregistrements des communications téléphoniques et électroniques entre un prestataire et ses clients, conformément à la réglementation MIF 2 ?', '["5 ans","3 ans","10 ans"]', 0, 'MIF 2 impose une conservation d''au moins 5 ans pour ces enregistrements.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client passe un ordre d''achat de 100 actions à cours limité à 50 euros, alors que le cours est à 52 euros. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement au cours de 52 euros","L''ordre est rejeté car le cours est supérieur à la limite","L''ordre est enregistré et sera exécuté si le cours atteint 50 euros ou moins"]', 2, 'Un ordre à cours limité n''est exécuté qu''au prix limite ou meilleur, donc il attend une baisse du cours.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation MIFID, quelle est l''obligation d''une entreprise d''investissement en matière de conflits d''intérêts ?', '["Elle doit toujours éviter tout conflit d''intérêts, sans exception.","Elle doit identifier, prévenir ou gérer les conflits d''intérêts et informer le client si les mesures ne suffisent pas.","Elle doit informer le client uniquement après la transaction."]', 1, 'L''entreprise doit gérer les conflits et informer le client si nécessaire, mais ne peut pas les éviter totalement.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité d''achat à 100 € est passé alors que le cours est de 105 €. Que se passe-t-il ?', '["L''ordre reste en attente jusqu''à ce que le cours atteigne 100 € ou moins.","L''ordre est exécuté immédiatement au cours de 100 €.","L''ordre est annulé automatiquement."]', 0, 'Un ordre à cours limité n''est exécuté que si le cours atteint le prix limite ou mieux.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la particularité d''un ordre à seuil de déclenchement (stop) ?', '["Il garantit l''exécution au prix du seuil.","Il est exécuté uniquement si le cours revient au seuil après l''avoir dépassé.","Il se transforme en ordre au marché une fois le seuil atteint."]', 2, 'Un ordre stop devient un ordre au marché dès que le seuil est touché, sans garantie de prix.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre un jeton utilitaire et un jeton de sécurité ?', '["Le jeton utilitaire confère des droits de propriété sur l''entreprise.","Le jeton de sécurité est soumis à la réglementation financière.","Le jeton utilitaire est toujours émis par une banque centrale."]', 1, 'Le jeton de sécurité représente un investissement et relève de la réglementation financière.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''impact d''une augmentation de la volatilité sur la valeur d''une option ?', '["La valeur de l''option augmente.","La valeur de l''option diminue.","La valeur de l''option reste inchangée."]', 0, 'Une volatilité accrue augmente la probabilité de mouvement du sous-jacent, donc la prime de l''option.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la tokenisation d''un actif immobilier, que représente le jeton ?', '["Un droit de vote uniquement.","Une garantie de rendement fixe.","Une part de propriété de l''actif."]', 2, 'Le jeton représente une fraction de propriété de l''actif immobilier.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale caractéristique d''un stablecoin adossé à une monnaie fiduciaire ?', '["Sa valeur est garantie par un algorithme.","Il est indexé sur la valeur d''une monnaie légale.","Il est émis par une banque centrale."]', 1, 'Le stablecoin est adossé à une réserve de monnaie légale pour maintenir sa parité.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Selon le règlement MiCA, un crypto-actif qui vise à maintenir une valeur stable en se référant à une seule monnaie officielle est qualifié de :', '["token de monnaie électronique","token adossé à des actifs","token utilitaire"]', 0, 'Le règlement MiCA définit le token de monnaie électronique comme un crypto-actif adossé à une seule monnaie officielle.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la fonction principale d''un token utilitaire (utility token) ?', '["Conférer des droits de vote dans la gouvernance de l''émetteur","Donner accès à un service ou à une fonctionnalité numérique","Représenter une créance sur l''émetteur"]', 1, 'Un token utilitaire donne accès à un bien ou un service numérique, sans conférer de droits financiers.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un hard fork sur une blockchain ?', '["La chaîne est temporairement interrompue puis reprend avec un nouveau protocole","Tous les détenteurs de crypto-actifs perdent leurs avoirs","La chaîne se divise en deux chaînes distinctes avec un historique commun jusqu''au fork"]', 2, 'Un hard fork crée une divergence permanente de la blockchain, aboutissant à deux chaînes indépendantes.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale différence entre un security token et un utility token ?', '["Le security token confère des droits financiers, le utility token donne accès à un service","Le security token est émis sur une blockchain privée, le utility token sur une publique","Le utility token est toujours régulé par l''AMF, le security token ne l''est jamais"]', 0, 'Un security token représente un investissement (droits financiers), un utility token donne droit à un usage.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un fork sur la valeur d''une crypto-actif ?', '["Il crée une nouvelle chaîne et peut diviser la communauté, impactant la valeur","Il supprime automatiquement la moitié des tokens en circulation","Il garantit une hausse de valeur pour les détenteurs existants"]', 0, 'Un fork divise la blockchain, créant une nouvelle monnaie et une incertitude qui affecte la valeur.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la caractéristique d''un ordre à plage de déclenchement (stop-limit) ?', '["Il combine un stop et un ordre limité, mais ne garantit pas l''exécution","Il est exécuté au meilleur prix disponible dès que le seuil est atteint","Il reste actif jusqu''à une date d''échéance fixée par l''émetteur"]', 0, 'Un stop-limit déclenche un ordre limité après un seuil, mais l''exécution dépend du marché.', 7, 'Instruments financiers et crypto-actifs');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un ordre de souscription d''OPCVM passé après l''heure limite de centralisation ?', '["Il est exécuté à la VL du lendemain","Il est exécuté à la VL du jour","Il est annulé"]', 0, 'Un ordre passé après l''heure limite est reporté au jour ouvré suivant, appliquant la VL du lendemain.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur achète 100 parts d''un OPCVM à une VL de 50 € avec des frais d''entrée de 2%. Quel est le montant total payé ?', '["5 000 €","5 100 €","5 200 €"]', 1, 'Le montant total est 100 parts × 50 € × 1,02 = 5 100 €.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans un compte de tiers, comment sont protégés les actifs des clients en cas de défaillance du gestionnaire ?', '["Ils sont saisis par les créanciers","Ils sont transférés au dépositaire","Ils sont protégés par la ségrégation"]', 2, 'La ségrégation des actifs sur un compte de tiers les protège des créanciers du gestionnaire.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la différence entre la valeur liquidative et le prix d''émission d''une part d''OPCVM ?', '["Le prix d''émission inclut les frais d''entrée","La VL inclut les frais de gestion","Ils sont identiques"]', 0, 'Le prix d''émission correspond à la VL augmentée des frais d''entrée.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur passe un ordre de souscription à 10h00 pour un OPCVM dont l''heure de centralisation est 12h00. Quelle sera la valeur liquidative utilisée pour l''exécution ?', '["La VL du jour même","La VL du jour ouvré suivant","La VL de la veille"]', 0, 'Les ordres reçus avant l''heure de centralisation sont exécutés sur la VL calculée le jour même.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Concernant le compte de tiers, quelle obligation incombe à l''établissement qui détient les actifs de ses clients ?', '["Les déposer sur un compte unique avec les actifs de l''établissement","Les conserver sur un compte distinct et séparé","Les prêter à d''autres clients"]', 1, 'Les actifs des clients doivent être conservés sur un compte distinct de celui de l''établissement pour éviter toute confusion.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre d''un fonds à formule, quelle caractéristique est généralement associée à la garantie du capital ?', '["La garantie est effective à tout moment","La garantie est conditionnelle à l''échéance et à certaines conditions de marché","La garantie est assurée par le dépositaire"]', 2, 'La garantie du capital dans un fonds à formule est généralement conditionnelle à l''échéance et à des conditions de marché.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence juridique de l''inscription des actifs d''un OPCVM sur un compte de tiers ?', '["Ils sont protégés en cas de faillite de la société de gestion","Ils appartiennent à la société de gestion","Ils sont disponibles pour les créanciers de la société de gestion"]', 0, 'Les actifs sur compte de tiers sont isolés du patrimoine de la société de gestion.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une souscription importante sur la valeur liquidative d''un OPCVM ?', '["Elle augmente la valeur liquidative","Elle diminue la valeur liquidative","Elle n''a aucun effet sur la valeur liquidative"]', 2, 'La VL est inchangée car l''actif net et le nombre de parts augmentent proportionnellement.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la différence entre un compte de tiers et un compte propre pour une société de gestion ?', '["Le compte de tiers est utilisé pour les opérations de la société, le compte propre pour les clients","Le compte de tiers est destiné aux fonds des clients, le compte propre aux fonds de la société","Le compte de tiers est soumis à l''impôt, le compte propre ne l''est pas"]', 1, 'Le compte de tiers sépare les avoirs clients de ceux de la société.', 8, 'Gestion collective / compte de tiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité garantit-il l''exécution ?', '["Oui, dès que le prix atteint la limite","Non, il ne garantit que le prix","Oui, si le marché est liquide"]', 1, 'Un ordre à cours limité ne garantit pas l''exécution, seulement le prix maximum ou minimum.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Que mesure l''écart entre le meilleur prix d''achat et le meilleur prix de vente ?', '["Le coût implicite de transaction","La volatilité du marché","Le volume échangé"]', 0, 'L''écart acheteur-vendeur représente le coût implicite de transaction, appelé spread.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel type d''ordre garantit une exécution immédiate mais pas le prix ?', '["Ordre à cours limité","Ordre au marché","Ordre à seuil de déclenchement"]', 1, 'L''ordre au marché est exécuté immédiatement au meilleur prix disponible, sans garantie de prix.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Qu''est-ce qu''un dark pool ?', '["Un marché réglementé où les ordres sont anonymes","Une plateforme de négociation pour les titres non cotés","Un système de négociation hors marché sans transparence pré-négociation"]', 2, 'Un dark pool est un système de négociation hors marché sans transparence pré-négociation.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la fonction principale d''une chambre de compensation (CCP) sur un marché organisé ?', '["Garantir la bonne fin des transactions en se substituant aux contreparties","Fixer les cours de clôture des valeurs","Assurer la liquidité en achetant et vendant pour son propre compte"]', 0, 'La CCP s''interpose entre acheteurs et vendeurs pour garantir l''exécution des transactions.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un ordre à cours limité d''achat placé en dessous du prix du marché ?', '["Il est exécuté immédiatement au prix limité","Il reste en attente dans le carnet d''ordres jusqu''à ce que le prix baisse","Il est annulé automatiquement à la clôture"]', 1, 'Un ordre à cours limité n''est exécuté que si le prix atteint la limite fixée.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Comment est calculé l''indice CAC 40 ?', '["Moyenne simple des cours des 40 plus fortes capitalisations","Capitalisation boursière pondérée des 40 valeurs les plus liquides","Moyenne pondérée par les volumes échangés des 40 valeurs"]', 2, 'Le CAC 40 est un indice pondéré par la capitalisation flottante des valeurs.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre d''achat à cours limité à 50 € est placé alors que le meilleur prix vendeur est à 49,5 €. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement à 49,5 €","L''ordre est enregistré dans le carnet à 50 €","L''ordre est exécuté à 50 €"]', 0, 'L''ordre d''achat limité à 50 € peut acheter à un prix inférieur, donc il s''exécute au meilleur prix vendeur.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la fonction principale d''un teneur de marché ?', '["Exécuter les ordres des clients en priorité","Fournir de la liquidité en affichant des prix acheteur et vendeur","Fixer le cours d''ouverture de la séance"]', 1, 'Le teneur de marché s''engage à coter en continu des prix acheteur et vendeur pour assurer la liquidité.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à seuil de déclenchement (stop) est un ordre qui...', '["Devient un ordre à cours limité dès que le seuil est atteint","Est annulé si le seuil n''est pas atteint avant la clôture","Est exécuté automatiquement au prix du marché dès que le seuil est atteint"]', 2, 'Un ordre stop se transforme en ordre au marché lorsque le cours atteint le seuil déclencheur.', 9, 'Fonctionnement et organisation des marchés');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle principal d''une contrepartie centrale (CCP) dans le post-marché ?', '["Garantir le règlement en devenant acheteur de chaque vendeur et vendeur de chaque acheteur","Conserver les titres pour le compte des investisseurs","Fournir une plateforme de négociation"]', 0, 'La CCP s''interpose entre acheteurs et vendeurs pour garantir le règlement des transactions.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Que garantit le règlement-livraison contre paiement (DVP) ?', '["La livraison des titres avant le paiement","La livraison des titres uniquement si le paiement est effectué simultanément","Le paiement après livraison avec un délai de crédit"]', 1, 'Le DVP assure que le transfert de titres et le paiement sont simultanés, éliminant le risque de principal.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Que signifie le règlement en J+2 ?', '["Deux jours après la confirmation de l''ordre","Date de négociation plus deux jours calendaires","Date de négociation plus deux jours ouvrés"]', 2, 'J+2 signifie règlement deux jours ouvrés après la date de transaction, standard en Europe.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle entité est généralement responsable de la tenue du registre officiel de propriété des titres ?', '["Le dépositaire central (CSD)","La chambre de compensation","La bourse"]', 0, 'Le CSD est responsable de la conservation des titres et de la tenue du registre de propriété.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le rôle principal d''une contrepartie centrale (CCP) dans le processus de compensation ?', '["Garantir l''exécution des transactions en devenant l''acheteur et le vendeur de chaque opération","Enregistrer les transactions et assurer la conservation des titres","Fixer les prix des instruments financiers sur le marché"]', 0, 'La CCP s''interpose entre les parties pour garantir la bonne fin des transactions.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''objectif principal de TARGET2-Securities (T2S) ?', '["Uniformiser les règles de négociation sur les marchés réglementés européens","Harmoniser le règlement-livraison de titres en euros dans une plateforme unique","Centraliser la surveillance des infrastructures de marché au niveau européen"]', 2, 'T2S est une plateforme de règlement-livraison de titres en monnaie de banque centrale, unifiant les systèmes de règlement en Europe.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la principale fonction d''une contrepartie centrale (CCP) dans le post-marché ?', '["S''interposer entre acheteurs et vendeurs pour garantir l''exécution des transactions","Conserver les titres et tenir les comptes des investisseurs","Assurer la compensation des paiements interbancaires"]', 0, 'La CCP s''interpose entre les parties, devenant contrepartie de chaque opération pour réduire le risque de défaut.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''objectif principal du mécanisme de livraison contre paiement (LCP) ?', '["Permettre le prêt de titres entre investisseurs","Réduire le risque de principal en liant le transfert de titres et le paiement","Accélérer le règlement en utilisant des monnaies différentes"]', 1, 'Le LCP garantit que la livraison des titres n''a lieu que si le paiement est effectué simultanément.', 10, 'Post-marché et infrastructures de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet immédiat d''une division du nominal d''une action (split) sur le capital social de la société ?', '["Le capital social est réduit","Le capital social reste inchangé","Le capital social augmente"]', 1, 'Un split modifie le nombre d''actions et le nominal, mais le capital social total reste identique.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans une émission obligataire, que représente le ''prix d''émission'' ?', '["Le prix auquel l''obligation sera remboursée","Le taux d''intérêt nominal de l''obligation","Le prix auquel l''obligation est vendue aux investisseurs lors de l''émission"]', 2, 'Le prix d''émission est le prix de souscription initial, distinct du prix de remboursement.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Une entreprise réalise une augmentation de capital de 100 millions d''euros par émission de 1 million d''actions nouvelles au prix de 100 euros. Quel est le montant du capital social augmenté si le nominal est de 10 euros ?', '["10 millions d''euros","100 millions d''euros","1 million d''euros"]', 0, 'Le capital social augmente du nominal multiplié par le nombre d''actions, soit 10€ * 1M = 10M€, la prime d''émission étant la différence.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital avec droits préférentiels de souscription, quel est l''effet mécanique sur le cours de l''action ?', '["Le cours augmente du montant du droit","Le cours diminue du montant du droit","Le cours reste inchangé"]', 1, 'Le détachement du droit de souscription entraîne une baisse mécanique du cours égale à la valeur du droit.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est l''incidence d''un split (division du nominal) sur le capital social d''une société cotée ?', '["Le capital social augmente","Le capital social diminue","Le capital social reste inchangé"]', 2, 'Un split modifie le nombre de titres mais pas le montant total du capital social.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre d''une émission obligataire, que signifie une prime d''émission ?', '["Le prix d''émission est supérieur au pair","Le prix d''émission est inférieur au pair","Le prix d''émission est égal au pair"]', 0, 'La prime d''émission correspond à un prix d''émission supérieur à la valeur nominale (pair).', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital par émission de droits préférentiels de souscription, quel est l''effet sur le prix de l''action existante ?', '["Le prix baisse car il y a dilution","Le prix monte car la société reçoit des fonds","Le prix reste inchangé car l''opération est neutre"]', 0, 'Le prix ex-droit est inférieur au prix cum-droit en raison de la dilution.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un regroupement d''actions (reverse split) sur le capital social d''une société ?', '["Il réduit le nombre d''actions sans changer le capital","Il augmente le capital social","Il réduit la valeur nominale des actions"]', 0, 'Le reverse split réduit le nombre d''actions, le capital social reste identique.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lorsqu''une société verse un dividende en numéraire, quel est l''impact sur le cours de l''action le jour du détachement du coupon ?', '["Le cours baisse du montant du dividende","Le cours monte du montant du dividende","Le cours reste inchangé car le dividende est une distribution de bénéfices"]', 0, 'Le cours est ajusté à la baisse du montant du dividende le jour du détachement.', 11, 'Émissions et opérations sur titres');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'En comptabilité d''engagement, une charge est comptabilisée :', '["au moment du paiement","au moment de la facturation","lorsque le bien est livré ou le service rendu"]', 2, 'En comptabilité d''engagement, les charges sont enregistrées lorsqu''elles sont encourues, indépendamment du paiement.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Le bilan d''une entreprise présente :', '["ses ressources et ses emplois","ses produits et ses charges","ses flux de trésorerie"]', 0, 'Le bilan récapitule les ressources (capitaux propres et dettes) et les emplois (actifs) à une date donnée.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Le taux de marque se calcule comme :', '["marge commerciale / coût d''achat","marge commerciale / prix de vente","marge commerciale / résultat net"]', 1, 'Le taux de marque exprime la marge commerciale en pourcentage du prix de vente.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'La méthode d''amortissement linéaire consiste à :', '["répartir la valeur d''un actif sur sa durée de vie de manière constante","amortir plus fortement les premières années","amortir selon l''usage réel"]', 0, 'L''amortissement linéaire répartit uniformément le coût de l''actif sur sa durée de vie.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une augmentation du délai de paiement accordé aux clients sur le besoin en fonds de roulement ?', '["Diminution","Augmentation","Aucun effet"]', 1, 'Le BFR augmente car les créances clients s''accroissent avant l''encaissement.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Une entreprise a un actif immobilisé de 200 000 € amortissable sur 10 ans en linéaire. Après 4 ans, quelle est la valeur nette comptable ?', '["120 000 €","80 000 €","160 000 €"]', 0, 'Amortissement annuel = 20 000 €, sur 4 ans = 80 000 €, valeur nette = 200 000 - 80 000 = 120 000 €.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''impact d''une augmentation du taux d''actualisation sur la valeur actuelle nette (VAN) d''un projet ?', '["Augmentation","Aucun effet","Diminution"]', 2, 'Une hausse du taux d''actualisation réduit la valeur des flux futurs, donc la VAN diminue.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''impact d''une écriture d''amortissement sur le résultat net et la trésorerie ?', '["Diminue le résultat net mais n''affecte pas la trésorerie","Diminue le résultat net et diminue la trésorerie","Augmente le résultat net et n''affecte pas la trésorerie"]', 0, 'L''amortissement est une charge non décaissée, il réduit le résultat mais pas la trésorerie.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Comment le fonds de roulement net global (FRNG) est-il calculé ?', '["Actif circulant - passif circulant","Trésorerie nette + dettes financières","Capitaux permanents - actif immobilisé"]', 2, 'Le FRNG est la différence entre les ressources stables (capitaux permanents) et les emplois stables (actif immobilisé).', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une hausse du taux d''actualisation sur la valeur actuelle nette (VAN) d''un projet ?', '["La VAN augmente","La VAN diminue","La VAN reste inchangée"]', 1, 'Une hausse du taux d''actualisation réduit la valeur actuelle des flux futurs, donc la VAN baisse.', 12, 'Bases comptables et financières');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de lutte contre le blanchiment, quelle est l''obligation d''une société de gestion ?', '["Déclarer à l''AMF toute opération suspecte","Déclarer à Tracfin toute opération suspecte","Transmettre un rapport annuel à l''ACPR sur les opérations suspectes"]', 1, 'Les sociétés de gestion doivent déclarer les opérations suspectes à Tracfin, cellule de renseignement financier.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée minimale de conservation des enregistrements téléphoniques pour les prestataires de services d''investissement ?', '["3 ans","5 ans","10 ans"]', 1, 'La réglementation MIFID II impose une conservation de 5 ans pour les enregistrements téléphoniques.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur achète une action à 100 €, perçoit un dividende de 5 € et la revend à 105 € après un an. Quel est son rendement total ?', '["5%","10%","15%"]', 1, 'Rendement total = (dividende + gain en capital) / prix initial = (5+5)/100 = 10%.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un capital de 10 000 € est placé à 2% par an à intérêts composés pendant 2 ans. Quel est le montant obtenu ?', '["10 400 €","10 404 €","10 200 €"]', 1, '10 000 × 1,02² = 10 404 €, car les intérêts s''ajoutent au capital.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle autorité est chargée de l''immatriculation des conseillers en investissements financiers (CIF) en France ?', '["AMF","ORIAS","ACPR"]', 1, 'Les CIF sont immatriculés auprès de l''ORIAS, qui tient le registre unique des intermédiaires.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En France, le seuil de déclaration de franchissement de participation dans une société cotée est fixé à quel pourcentage du capital ?', '["5%","10%","3%"]', 0, 'Le seuil légal de déclaration est de 5% du capital ou des droits de vote.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Si une société procède à une division du nominal de ses actions (split 1 pour 2), le cours de l''action...', '["double","diminue de moitié","reste inchangé"]', 1, 'Le split augmente le nombre d''actions, réduisant le cours proportionnellement.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la directive MIFID II, quelle est la durée minimale de conservation des enregistrements relatifs aux ordres et transactions ?', '["3 ans","5 ans","10 ans"]', 1, 'La directive MIFID II impose une conservation de 5 ans pour les enregistrements d''ordres et de transactions.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la sanction pécuniaire maximale que peut prononcer la Commission des sanctions de l''AMF à l''encontre d''une personne morale ?', '["100 millions d''euros ou 10% du chiffre d''affaires","50 millions d''euros","10 millions d''euros"]', 0, 'La sanction maximale pour une personne morale est de 100 millions d''euros ou 10% du chiffre d''affaires annuel.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une augmentation du taux de réserves obligatoires sur la création monétaire par les banques ?', '["Elle augmente","Elle reste inchangée","Elle diminue"]', 2, 'Une hausse du taux de réserves obligatoires réduit la capacité des banques à prêter, donc diminue la création monétaire.', 1, 'Cadre institutionnel et réglementaire');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Une société de gestion de portefeuille est tenue de mettre en place une fonction de conformité. Quelle proposition est exacte ?', '["Cette fonction peut être externalisée sans condition.","Cette fonction doit être indépendante et permanente.","Cette fonction est optionnelle pour les sociétés de moins de 50 millions d''actifs."]', 1, 'La fonction de conformité doit être indépendante et permanente, selon les exigences réglementaires.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de prévention du blanchiment, quelle est l''obligation d''un prestataire de services d''investissement ?', '["Il doit conserver les documents pendant 10 ans.","Il doit déclarer toute opération supérieure à 10 000 euros.","Il doit déclarer toute opération suspecte à Tracfin."]', 2, 'Les PSI doivent déclarer à Tracfin les opérations suspectes de blanchiment.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre du devoir de conseil, qu''est-ce que l''adéquation ?', '["L''obligation de recommander des instruments adaptés au profil du client.","L''obligation de fournir une information claire et non trompeuse.","L''obligation d''exécuter les ordres aux meilleures conditions."]', 0, 'L''adéquation impose de recommander des produits cohérents avec le profil, l''expérience et les objectifs du client.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Une société de gestion est tenue à certaines obligations en matière de lutte contre le blanchiment : quelle proposition est exacte ?', '["Elle doit déclarer à Tracfin toute opération suspecte dès qu''elle en a connaissance.","Elle doit conserver les documents relatifs aux opérations pendant 3 ans.","Elle est dispensée de désignation d''un correspondant LCB-FT si elle a moins de 10 salariés."]', 0, 'La déclaration à Tracfin est obligatoire dès connaissance d''une opération suspecte, sans délai.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En matière de déontologie, quelle est l''obligation d''une société de gestion concernant les opérations personnelles de ses salariés ?', '["Les salariés sont libres d''effectuer des opérations personnelles sans déclaration préalable.","Les salariés doivent déclarer leurs opérations personnelles à la société de gestion, qui en assure le contrôle.","Seuls les dirigeants sont soumis à une déclaration, les autres salariés en sont exemptés."]', 1, 'La réglementation impose une déclaration des opérations personnelles pour prévenir les conflits d''intérêts.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un gérant de portefeuille souhaite exécuter un ordre pour un client. Quel est le principe de la meilleure exécution ?', '["Il doit toujours exécuter l''ordre sur le marché réglementé le plus proche.","Il doit exécuter l''ordre au prix moyen du marché à la clôture.","Il doit obtenir le meilleur résultat possible en termes de prix, coûts, rapidité et probabilité d''exécution."]', 2, 'La meilleure exécution impose de considérer plusieurs facteurs pour obtenir le meilleur résultat pour le client.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Un conseiller en investissements financiers (CIF) doit, en cas de conflit d''intérêts, adopter quel comportement ?', '["Le signaler uniquement à l''AMF","Le taire si le conflit est mineur","Le révéler au client et obtenir son accord"]', 2, 'Le CIF doit informer le client de tout conflit d''intérêts et obtenir son accord avant de poursuivre.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la sanction maximale encourue par une personne physique pour un délit d''initié ?', '["7 ans d''emprisonnement et 1,5 million d''euros d''amende","5 ans d''emprisonnement et 100 000 € d''amende","10 ans d''emprisonnement et 10 millions d''euros d''amende"]', 0, 'Le délit d''initié est puni de 7 ans d''emprisonnement et 1,5 million d''euros d''amende pour les personnes physiques.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client effectue deux versements en espèces de 6 000 € chacun à un mois d''intervalle. Selon les obligations de lutte contre le blanchiment, le professionnel doit-il déclarer ?', '["Non, car chaque versement est inférieur à 10 000 €","Oui, car il s''agit d''une opération fractionnée","Oui, car le total dépasse 10 000 €"]', 1, 'Le fractionnement d''opérations pour rester sous le seuil de déclaration constitue un indice de blanchiment imposant la déclaration.', 2, 'Déontologie et conformité');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'En application de la réglementation LCB-FT, quelle obligation s''impose aux personnes soumises lors d''une relation d''affaires avec une personne politiquement exposée (PPE) ?', '["Mettre en place des mesures de vigilance simples","Mettre en place des mesures de vigilance renforcées","S''abstenir de toute relation d''affaires"]', 1, 'Les PPE exigent des mesures de vigilance renforcées, notamment pour identifier l''origine des fonds.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''un ordre de gel des avoirs sur un compte bancaire ?', '["Le compte est clôturé définitivement","Les fonds sont bloqués, mais les intérêts continuent de courir","Le compte peut être utilisé pour des opérations courantes jusqu''à un certain montant"]', 2, 'Le gel bloque les fonds mais n''empêche pas la capitalisation des intérêts.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation LCB-FT, quelle est l''obligation d''une entreprise du secteur financier lorsqu''elle constate une opération suspecte ?', '["La déclarer à Tracfin","La déclarer à l''AMF","La signaler à la Banque de France"]', 0, 'Toute opération suspecte doit être déclarée à Tracfin, la cellule de renseignement financier française.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre des mesures d''embargo, quel organe est chargé de la mise en œuvre des sanctions financières ciblées en France ?', '["L''Autorité des marchés financiers (AMF)","Le ministère de l''Économie et des Finances","Le Conseil des marchés financiers"]', 1, 'Le ministère de l''Économie (Direction générale du Trésor) est responsable de la mise en œuvre des sanctions financières.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est le seuil de transaction occasionnelle à partir duquel une entreprise assujettie doit procéder à l''identification du client en application de la LCB-FT ?', '["10 000 euros","20 000 euros","15 000 euros"]', 2, 'Le seuil est fixé à 15 000 euros pour les transactions occasionnelles selon l''article R561-16 du Code monétaire et financier.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la réglementation LCB-FT, quelle est la règle applicable à la déclaration de soupçon ?', '["Elle doit être faite après exécution de l''opération","Elle doit être faite avant l''exécution de l''opération, sauf impossibilité","Elle est facultative pour les opérations inférieures à 10 000 euros"]', 1, 'La déclaration doit précéder l''opération, sauf impossibilité de la différer.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la différence entre le gel des avoirs et la confiscation ?', '["Le gel est une mesure conservatoire, la confiscation est une sanction définitive","Le gel est définitif, la confiscation est temporaire","Ils sont identiques"]', 0, 'Le gel bloque temporairement les fonds, la confiscation les transfère définitivement à l''État.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de l''approche par les risques, quel élément constitue un facteur de risque élevé ?', '["Un client effectuant des opérations de faible montant","Un client ayant une activité commerciale régulière","Un client résidant dans un pays non coopératif"]', 2, 'Les pays non coopératifs sont considérés à haut risque selon les recommandations du GAFI.', 3, 'Sécurité financière (LCB-FT, embargos)');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle obligation incombe à une société de gestion en cas de suspicion d''abus de marché ?', '["Signaler immédiatement à l''AMF toute transaction suspecte","Attendre la fin de la journée de cotation avant tout signalement","Informer uniquement l''émetteur concerné de la suspicion"]', 0, 'Les sociétés de gestion doivent déclarer sans délai les transactions suspectes à l''AMF.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle opération constitue une manipulation de marché ?', '["Passer des ordres sans intention d''exécution pour créer une fausse liquidité","Acheter des titres après une publication de résultats positifs","Vendre des titres pour rééquilibrer un portefeuille"]', 0, 'Les ordres fictifs ou annulés visant à tromper le marché sont une manipulation typique.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle est la conséquence d''une information privilégiée non publiée sur un ordre ?', '["L''ordre est interdit si l''information est déterminante pour la décision","L''ordre est autorisé si l''information est positive","L''ordre est toléré si l''exécution est immédiate"]', 0, 'Utiliser une information privilégiée pour négocier constitue un délit d''initié, même en cas d''exécution rapide.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle est l''obligation d''une personne exerçant des responsabilités dirigeantes (PMDR) concernant ses transactions sur les titres de son émetteur ?', '["Les notifier à l''émetteur et à l''autorité compétente sous 3 jours ouvrés","Les déclarer uniquement à l''émetteur sous 5 jours calendaires","Les publier sur le site de l''émetteur le jour même de la transaction"]', 0, 'Les PMDR doivent notifier leurs transactions dans un délai de 3 jours ouvrés.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''une opération de ''wash trade'' (transaction fictive) sur le marché ?', '["Elle garantit un profit à l''initiateur","Elle constitue une couverture légitime","Elle crée un volume artificiel sans transfert de propriété"]', 2, 'Les wash trades donnent une fausse indication de liquidité, sans changement de bénéficiaire.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon le règlement MAR, quelle proposition définit correctement une information privilégiée ?', '["Information précise, non publique, susceptible d''influencer sensiblement le cours.","Information publique mais susceptible d''influencer le cours.","Information confidentielle sans impact potentiel sur le cours."]', 0, 'La définition exige précision, non-publicité et impact potentiel sur le cours.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quelle pratique est un exemple de manipulation de marché selon le règlement MAR ?', '["Publier une information privilégiée après sa diffusion publique.","Passer des ordres sans intention de les exécuter.","Exécuter un ordre à cours limité sur un marché réglementé."]', 1, 'Le spoofing, ordres sans intention d''exécution, est une manipulation de marché.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Quel est l''effet d''un programme de rachat d''actions conforme au règlement MAR ?', '["Il est toujours considéré comme une manipulation de marché.","Il est soumis à une autorisation préalable de l''AMF.","Il bénéficie d''une présomption de conformité."]', 2, 'Les rachats conformes au MAR bénéficient d''une présomption de conformité.', 4, 'Réglementation abus de marché');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MiFID II, quelle est l''obligation d''une entreprise d''investissement concernant les informations sur les coûts et charges ?', '["Les informations ne sont requises qu''après l''exécution de la transaction.","Les informations doivent être fournies avant la prestation du service, en incluant les coûts liés au service et à l''instrument.","Les informations ne sont nécessaires que pour les clients professionnels."]', 1, 'MiFID II impose une information précontractuelle complète sur les coûts et charges, avant la prestation.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la définition d''un ''client professionnel sur demande'' ?', '["Un client de détail qui demande à être traité comme un professionnel, sous réserve de critères quantitatifs et qualitatifs.","Un client qui a signé un contrat de conseil avec l''entreprise.","Un client qui détient un portefeuille supérieur à 500 000 euros."]', 0, 'Le client professionnel sur demande est un client de détail qui, sur sa demande, est traité comme professionnel s''il satisfait à des critères.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Qu''est-ce que l''indicateur synthétique de risque et de rendement (SRRI) d''un OPCVM ?', '["Le ratio de frais totaux du fonds.","La performance annualisée sur 10 ans.","Une échelle de 1 à 7 qui classe le fonds selon son niveau de risque."]', 2, 'Le SRRI est un indicateur réglementaire allant de 1 (risque faible) à 7 (risque élevé).', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le cadre de la commercialisation d''un produit structuré, que signifie ''capital garanti'' ?', '["Le capital est garanti en cas de faillite de l''émetteur.","Le capital est restitué à l''échéance, quelle que soit l''évolution du sous-jacent.","Le capital est investi sans risque de perte en cours de vie."]', 1, 'Le capital garanti signifie que l''investisseur récupère sa mise à l''échéance, mais pas nécessairement en cas de défaut de l''émetteur.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est l''obligation d''un conseiller en investissements financiers (CIF) lors de la commercialisation d''instruments financiers ?', '["Il doit garantir la performance des instruments proposés.","Il doit fournir une information exacte, claire et non trompeuse sur les caractéristiques des instruments.","Il doit uniquement proposer des instruments recommandés par son réseau."]', 1, 'Le CIF doit respecter une obligation d''information loyale et non trompeuse, sans garantie de performance.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon la directive MIFID II, que doit faire un prestataire de services d''investissement avant de fournir un service de conseil en investissement ?', '["Évaluer l''adéquation de l''instrument au client (test d''adéquation).","Obtenir l''accord écrit du client sur chaque transaction.","Vérifier la solvabilité du client."]', 0, 'Le conseil en investissement exige une évaluation de l''adéquation (suitability) pour le client.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Lors d''une augmentation de capital avec maintien du droit préférentiel de souscription (DPS), que se passe-t-il pour un actionnaire qui ne souhaite pas souscrire ?', '["Il perd automatiquement ses droits sans compensation.","Il doit obligatoirement souscrire pour éviter la dilution.","Il peut vendre ses DPS sur le marché, ce qui compense partiellement la dilution."]', 2, 'L''actionnaire peut céder ses DPS, ce qui lui permet de monétiser la valeur du droit.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle obligation s''impose à un conseiller en investissements financiers (CIF) lors de la fourniture d''un service de conseil en investissement ?', '["Fournir un rapport écrit sur l''adéquation du conseil à la situation du client.","Vérifier que le client est un investisseur professionnel avant de le conseiller.","Transmettre l''ordre au marché dans les meilleurs délais."]', 0, 'Le CIF doit évaluer l''adéquation et fournir un rapport écrit conformément à la réglementation MIFID.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la durée de validité d''un prospectus approuvé par l''AMF pour une offre au public de titres financiers ?', '["6 mois","12 mois","24 mois"]', 1, 'Selon le règlement Prospectus, un prospectus est valable 12 mois après son approbation.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un investisseur passe un ordre à cours limité d''achat à 50 € pour une action cotée à 52 €. Si le marché ne descend pas à ce niveau, que se passe-t-il ?', '["L''ordre est exécuté au prix du marché.","L''ordre est automatiquement annulé en fin de séance.","L''ordre n''est pas exécuté et reste en attente."]', 2, 'Un ordre à cours limité n''est exécuté que si le prix atteint le niveau fixé ; sinon, il reste actif.', 5, 'Commercialisation d''instruments financiers');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la relation avec un client, quelle est l''obligation d''un prestataire de services d''investissement en matière de conflits d''intérêts ?', '["Il doit identifier les conflits d''intérêts et, si nécessaire, les prévenir ou les gérer, et informer le client si la gestion ne suffit pas.","Il doit les ignorer car ils sont inhérents à l''activité.","Il doit les déclarer systématiquement à l''AMF avant chaque transaction."]', 0, 'Le prestataire doit gérer les conflits d''intérêts et informer le client si la gestion ne suffit pas.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Lors de la fourniture d''un service de conseil en investissement, quelle information le prestataire doit-il recueillir pour évaluer l''adéquation ?', '["Uniquement le profil de risque du client.","Les connaissances et l''expérience, la situation financière et les objectifs d''investissement.","Uniquement les objectifs de rendement."]', 1, 'L''évaluation de l''adéquation nécessite ces trois éléments.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Dans le carnet d''ordres, un ordre d''achat à cours limité sera prioritaire si :', '["il a le prix le plus élevé et la date de saisie la plus ancienne.","il a le prix le plus bas et la date de saisie la plus ancienne.","il a le prix le plus élevé et la date de saisie la plus récente."]', 0, 'La priorité est donnée au prix le plus élevé pour un achat, puis à l''antériorité.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Selon MiFID II, quelle est la durée minimale de conservation des enregistrements des communications téléphoniques avec les clients ?', '["3 ans","5 ans","10 ans"]', 1, 'La réglementation impose une conservation minimale de 5 ans pour ces enregistrements.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Quelle est la fréquence minimale de transmission aux clients du rapport sur la qualité d''exécution des ordres ?', '["Annuelle","Semestrielle","Trimestrielle"]', 0, 'Le rapport doit être fourni au moins une fois par an aux clients.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client vend 100 actions au marché. Le carnet d''ordres affiche un meilleur prix acheteur de 50 € pour 50 actions, puis 49,95 € pour 50 actions. Quel est le prix moyen d''exécution ?', '["49,95 €","50,00 €","49,975 €"]', 2, 'Le prix moyen est calculé en pondérant les quantités : (50*50 + 49,95*50)/100 = 49,975 €.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('A', 'Dans le cadre de la relation client, pour quel service d''investissement le test de caractère approprié est-il obligatoire ?', '["Le conseil en investissement","L''exécution d''ordres","La gestion sous mandat"]', 1, 'Le test de caractère approprié s''applique aux services autres que le conseil et la gestion, comme l''exécution d''ordres.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un ordre à cours limité d''achat est passé à 100 € alors que le cours est de 105 €. Que se passe-t-il ?', '["L''ordre est exécuté immédiatement à 105 €","L''ordre est exécuté à 100 €","L''ordre reste en attente"]', 2, 'Un ordre à cours limité d''achat ne s''exécute que si le cours est inférieur ou égal à la limite.', 6, 'Relations avec les clients');
INSERT INTO questions (type, question, choices, correctIndex, explanation, themeId, theme) VALUES ('C', 'Un client investit 5 000 € dans un fonds avec des frais d''entrée de 3 %. Quel est le montant net investi ?', '["4 850 €","5 150 €","4 500 €"]', 0, 'Les frais d''entrée de 3 % sur 5 000 € représentent 150 €, donc le montant net est de 4 850 €.', 6, 'Relations avec les clients');
